"d.h1": "用 flatkey 构建",
"d.hp": "官方模型网关。一个 key 路由到 100+ 真实实验室端点——文本、视频、语音,每一次调用背后都有签约 SLA。",
"d.search": "搜索文档,或直接提问…",
"d.st1": "签约 SLA · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">条款</a>",
"d.st2": "TOKENS / 月",
"d.st3": "官方模型",
"d.st4": "协议:OPENAI + ANTHROPIC",
"d.card1p": "OpenAI 兼容端点 router.flatkey.ai/v1。改 base_url,SDK 不动——对话、工具、流式、结构化输出。",
"d.card2p": "原生 Anthropic API 形态——Claude Code、Cline 指向同一个 base URL,用 sk-fk-… key 即可。没有翻译层。",
"d.card3h": "媒体模型",
"d.card3p": "Seedance 2.5 视频、实时语音、TTS 与转写——按秒或按字符计费,共用同一余额。",
"d.card4h": "团队治理",
"d.card4p": "一人一 key,带限额与模型白名单;逐请求台账、配额与费用 API 给财务。",
"d.qsh": "从一次调用开始",
"d.qsp": "大多数人从这里开始:控制台建 key,改 base_url,发请求。三行代码,零基础设施。",
"d.llm": "用 AI agent 构建?抓取完整文档索引 <a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a>——每页都有纯 markdown 镜像(.md)。",
"d.gh": "指南——大家最常问的四件事",
"d.c1k": "编程 AGENT · CODEX CLI",
"d.c1h": "接入 Codex",
"d.c1s1": "一键:<span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> 安装器询问时选 <code>Codex CLI</code>。",
"d.c1s2": "手动:Codex 里选 <b>API key 登录</b>,base URL 填 <code>https://router.flatkey.ai/v1</code>,粘贴你的 <code>sk-fk-…</code> key。",
"d.c1s3": "分组返回 503?在 key 编辑器里把 key 切到另一个分组(见下方「分组与路由」)。",
"d.c2k": "编程 AGENT · ANTHROPIC 协议",
"d.c2h": "接入 Claude Code / Cline",
"d.c2s1": "设两个环境变量:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows 用 <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "或写进 <code>~/.claude/settings.json</code> 持久化:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "照常运行 <code>claude</code>。Cline:选 <b>Anthropic</b> 供应商,同样的 base URL + key。",
"d.c3k": "团队 · KEY、分组与限额",
"d.c3h": "一人一 key,一 key 一限额",
"d.c3s1": "在 <b>控制台 → API Keys</b> 给每位成员建一个 key;每个 key 设月度 <code>限额</code> 和可选的模型白名单。",
"d.c3s2": "<b>分组决定路由池,不是绑定人</b>:<code>Standard</code> = 聚合官方渠道(默认);<code>Economy</code> = 最低价专线。一个 key 属于一个分组,随时可换。",
"d.c3s3": "每个 key 的花费、分类 token 用量和剩余额度:看 <b>Usage &amp; Logs</b> 或调台账 API。",
"d.c4k": "计费 · 价格与缓存,大白话",
"d.c4h": "每个数字是什么意思",
"d.tblh": "<th>价格</th><th>含义</th>",
"d.tbl1": "每发送 100 万 prompt token",
"d.tbl2": "每生成 100 万 token",
"d.tbl3": "重复发送的前缀 token,约输入价 10% · 各厂缓存 5–60 分钟",
"d.c4s1": "<b>30 天健康度</b> = 最近 30 天真实生产流量的请求成功率,不是合成探测。",
"d.c4s2": "失败请求(5xx)一律不计费;故障切换只按真正应答的模型计费。 <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">完整 SLA →</a>",
"d.cmh": "社区",
"d.cmp": "开发者互相解答——路由配置、agent 接法、模型选型。团队全员盯帖;gateway-bench 和审计日志都在公开开发。",
