"cp.c1p": "No compramos tarjetas ni cargamos con el capex. Agregamos la oferta y enrutamos al precio más bajo, y luego lo envolvemos en un único punto de entrada empresarial con SLA. Más barato que poseer, más estable que el spot en bruto.",
"cp.c2t": "Inferencia ↔ cómputo, circuito cerrado",
"cp.c2p": "Tus modelos, tu facturación y tu equipo ya viven aquí. Pasar de \"usar un modelo\" a \"reservar su capacidad\" no tiene fricción, y es una sola factura en lugar de dos proveedores.",
"cp.c3t": "Flota Apple Silicon de gran memoria",
"cp.c3p": "Una máquina de 512GB de memoria unificada ejecuta un modelo de 671B en un solo nodo, más una flota global de Apple Silicon. Inferencia de gran memoria y eficiencia energética que ninguna nube puramente NVIDIA puede igualar.",
"cp.c4t": "Grado empresarial, facturación unificada",
"cp.c4p": "Aislamiento privado, presupuestos y cuotas por equipo, spend API y un objetivo de SLA público: inferencia y cómputo en una sola factura que tu equipo de finanzas realmente puede conciliar.",
"cp.s4eye": "Ancla de precios",
"cp.s4h": "Al precio del suelo del mercado",
"cp.tmodel": "Modelo",
"cp.tm1": "Clústeres privados",
"cp.tm2": "Clúster bajo demanda",
