"cp.tm5": "Despliega tu propia app",
"cp.tm6a": "desde $1.79/hr",
"cp.tm6b": "desde $0.99/hr",
"cp.tm6c": "Autoservicio + dedicado + SLA",
"cp.note": "Autoservicio desde hoy: alquila una RTX 4090 desde $0.72/hr con SSH, o ejecuta modelos por token y video por segundo — todo desde un solo saldo. El suministro de backend se obtiene por precio en mercados agregados, así que un endpoint H100 dedicado sigue quedando por debajo de Lambda / CoreWeave / Novita bajo demanda, sumando un SLA empresarial, aislamiento privado y facturación unificada que el spot en bruto no puede ofrecer. El margen viene del enrutamiento y la medición, no de cargar con hardware inactivo. Los precios ancla reflejan tarifas públicas del 2026-07-17; las tarifas de autoservicio son indicativas y se muestran en vivo en la consola.",
"cp.s5eye": "Para quién es",
"cp.s5h": "Creado para equipos que ejecutan inferencia a escala",
"cp.w1t": "Empresas de agentes y apps de IA",
"cp.w1p": "Unos pocos modelos concentran la mayor parte de tu tráfico. Reserva capacidad dedicada para ellos a precio de suelo, sin salir de la plataforma con la que ya facturas.",
"cp.w2t": "Despliegue privado y cumplimiento",
"cp.w2p": "Trae tu propio modelo o fine-tune, alójalo bajo aislamiento privado y enrútalo a través de tus claves y cuotas existentes.",
"cp.leadh": "¿Necesitas capacidad dedicada o despliegue privado?",
"cp.leadsub": "El autoservicio ya está disponible en la consola: empieza cuando quieras. Para un endpoint reservado de un solo inquilino, aislamiento privado o una cotización por volumen, cuéntanos qué estás ejecutando y volveremos con números. English / 中文 ambos válidos.",
