"tu.faqh": "FAQ de precios",
"tu.q1": "¿Qué incluye un plan?",
"tu.a1": "Una asignación mensual de uso — hasta $45 en Go, $90 en Pro, $300 en Max — válida en los 100+ modelos, más media credits para generar imagen y vídeo. Ventanas cortas de 5 horas y 7 días mantienen el servicio rápido para todos.",
"tu.q2": "¿Es una suscripción mensual?",
"tu.a2": "El pago por uso no tiene suscripción ni caducidad. Go, Pro y Max se renuevan mensualmente y pueden cancelarse en cualquier momento; después de la asignación mensual, la misma key continúa con tu saldo de pago por uso.",
"tu.q3": "¿Qué modelos cubre un plan?",
"tu.a3": "Todos los planes cubren GPT, Claude, Gemini, DeepSeek y los modelos de imagen, audio y vídeo — por un gateway compatible con OpenAI.",
"tu.q4": "¿Puedo ver cómo se consume el saldo?",
"tu.a4": "Sí. El uso se mide por modelo, tipo de token y logs de petición para revisar gasto y controlar costes.",
"tu.q5": "¿Cuándo elegir Enterprise?",
"tu.a5": "Con mayor uso mensual, facturación, compras, descuentos de routing a medida o controles de equipo.",
