"pr.sub": "Paga por uso sin compromiso mensual o suscríbete a Go, Pro o Max para obtener más uso de modelos. Incluye los 100+ modelos — GPT, Claude, Gemini, DeepSeek, Kimi, GLM, más imagen y vídeo Seedance. <b>Los contratos enterprise cuestan menos que self-serve</b>.",
