"nav.sla": "SLA",
"s.kick": "SLA · OBJETIVO PÚBLICO · CRÉDITOS ENTERPRISE",
"s.h1": "Un SLA que puedes<br>llevar a compras.",
"s.sub": "No es una promesa comercial: un documento público con objetivo de disponibilidad, método de medición y un proceso de incidencias definido. Los contratos enterprise añaden créditos contractuales y un objetivo mayor.",
"s.cta1": "Estado en vivo →",
"s.cta2": "Texto legal completo ↗",
"s.cta3": "SLA Enterprise",
"s.big.k": "COMPROMISO MENSUAL DE DISPONIBILIDAD",
"s.big.p": "Medido sobre los servicios cubiertos — API del router, endpoint Anthropic, consola y medición — por nuestros monitores de producción, por mes natural. Planes enterprise: 99.9% con enrutamiento prioritario.",
"s.p1k": "FAILOVER",
"s.p1h": "5 clases de canal, automático",
"s.p1p": "Cada modelo se sirve por hasta cinco clases de canal upstream. Los chequeos de salud son continuos; si un canal se degrada, las peticiones se redirigen al mejor canal oficial siguiente con reintentos automáticos.",
"s.p2k": "MEDICIÓN JUSTA",
"s.p2h": "Los errores no consumen saldo",
"s.p2p": "La facturación se liquida sobre tokens confirmados tras la respuesta; los errores devueltos por flatkey nunca consumen saldo. Un failover factura solo el modelo que respondió.",
"s.p3k": "TRANSPARENCIA",
"s.p3h": "Puedes verificarlo todo",
"s.p3p": "La <a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">página de estado</a> muestra 90 días de uptime por componente; cada modelo muestra su tasa de éxito de 30 días con tráfico real. Sin números sintéticos.",
"s.credh": "Créditos de servicio — acuerdos enterprise",
"s.credp": "Bajo términos estándar la remediación es caso por caso según el SLA público. Los acuerdos enterprise definen un esquema contractual de créditos — estructura típica:",
"s.tblh": "<th>DISPONIBILIDAD MENSUAL</th><th>CRÉDITO</th><th>CÓMO LLEGA</th>",
"s.row12": "abonado al saldo en 5 días hábiles tras aprobar la reclamación",
"s.row3": "se abona el 100% del uso del mes",
"s.fine": "Los créditos aplican al uso del servicio cubierto en el mes afectado. Reclamaciones: email a support@flatkey.ai en 30 días con request IDs o marcas de tiempo; la fuente de medición son nuestros registros de monitoreo. Exclusiones según el texto legal: caídas de laboratorios fuera del alcance del failover, mantenimiento programado con aviso, fuerza mayor y problemas de configuración del cliente.",
"s.clmh": "Cómo funciona una reclamación",
"s.st1b": "Detéctalo",
"s.st1p": "Ve el servicio degradado en la página de estado o en tus logs. Guarda request IDs o una ventana de tiempo.",
"s.st2b": "Preséntala",
"s.st2p": "Email a support@flatkey.ai — asunto \"SLA claim\", email de cuenta, endpoint afectado, timestamps. Respuesta en 1 día hábil.",
"s.st3b": "Cobra el crédito",
"s.st3p": "Conciliamos contra el monitoreo de producción y abonamos tu saldo. Sin discutir con un chatbot.",
"s.moreh": "¿Necesitas más de 99.5%?",
"s.morep": "Los acuerdos enterprise añaden objetivo de 99.9%, enrutamiento prioritario en incidentes, canal de soporte dedicado (Slack o WeChat) y esquemas de crédito a medida — en el contrato, no en una diapositiva.",
