"d.h1": "Construye con flatkey",
"d.hp": "Gateway de modelos oficiales. Una key enruta a 100+ endpoints reales — texto, vídeo, voz — con SLA firmado en cada llamada.",
"d.search": "Busca en los docs, o pregunta lo que sea…",
"d.st1": "SLA FIRMADO · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">TÉRMINOS</a>",
"d.st2": "TOKENS / MES",
"d.st3": "MODELOS OFICIALES",
"d.st4": "PROTOCOLOS: OPENAI + ANTHROPIC",
"d.card1p": "Endpoint compatible con OpenAI en router.flatkey.ai/v1. Cambia el base_url, conserva tu SDK — chat, tools, streaming, salida estructurada.",
"d.card2p": "Forma nativa de la API Anthropic — apunta Claude Code o Cline al mismo base URL con tu key sk-fk-…. Sin capa de traducción.",
"d.card3h": "Modelos de media",
"d.card3p": "Vídeo Seedance 2.5, voz en tiempo real, TTS y transcripción — por segundo o por carácter, en el mismo saldo.",
"d.card4h": "Gobernanza de equipo",
"d.card4p": "Una key por miembro con límites y allowlists; libro mayor por petición, cuotas y API de gasto para finanzas.",
"d.qsh": "Empieza con una llamada",
"d.qsp": "La mayoría empieza aquí: crea una key en la consola, cambia el base_url, envía una petición. Tres líneas, sin infraestructura.",
"d.llm": "¿Construyes con un agente IA? Descarga el índice completo en <a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a> — cada página tiene espejo markdown (.md).",
"d.gh": "Guías — las cuatro cosas que todos preguntan",
"d.c1k": "CODING AGENTS · CODEX CLI",
"d.c1h": "Conectar Codex",
"d.c1s1": "Una línea: <span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> y elige <code>Codex CLI</code> cuando pregunte.",
"d.c1s2": "Manual: en Codex elige <b>API key login</b>, base URL <code>https://router.flatkey.ai/v1</code>, pega tu key <code>sk-fk-…</code>.",
"d.c1s3": "¿Un grupo devuelve 503? Cambia la key a otro grupo en el editor de keys (ver Grupos y enrutamiento).",
"d.c2k": "CODING AGENTS · PROTOCOLO ANTHROPIC",
"d.c2h": "Conectar Claude Code / Cline",
"d.c2s1": "Dos variables de entorno:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows: <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "O persiste en <code>~/.claude/settings.json</code>:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "Ejecuta <code>claude</code> como siempre. Cline: proveedor <b>Anthropic</b>, mismo base URL + key.",
"d.c3k": "EQUIPOS · KEYS, GRUPOS Y CUOTAS",
"d.c3h": "Una key por persona, un límite por key",
"d.c3s1": "Crea una key por compañero en <b>Consola → API Keys</b>; fija un <code>límite</code> mensual y allowlist opcional por key.",
"d.c3s2": "<b>Los grupos eligen el pool de enrutamiento, no la persona</b>: <code>Standard</code> = canales oficiales agregados (por defecto); <code>Economy</code> = línea dedicada más barata. Una key pertenece a un grupo y se puede mover.",
"d.c3s3": "Gasto por key, tokens por tipo y cuota restante: <b>Usage &amp; Logs</b> o la API de libro mayor.",
"d.c4k": "FACTURACIÓN · PRECIOS Y CACHÉ, EN CLARO",
"d.c4h": "Qué significa cada número",
"d.tblh": "<th>PRECIO</th><th>SIGNIFICADO</th>",
"d.tbl1": "por 1M de tokens de prompt enviados",
"d.tbl2": "por 1M de tokens generados",
"d.tbl3": "tokens de prefijo reenviados, ~10% del precio de input · caché de 5–60 min según lab",
"d.c4s1": "<b>Salud 30 días</b> = % de peticiones exitosas en los últimos 30 días, tráfico real.",
"d.c4s2": "Las peticiones fallidas (5xx) nunca se facturan; el failover factura solo el modelo que respondió. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA completo →</a>",
"d.cmh": "Comunidad",
"d.cmp": "Builders respondiendo a builders — configs de enrutamiento, setups de agentes, elección de modelos. El equipo lo lee todo; gateway-bench y el audit log se desarrollan en abierto.",
