"tu.tv23": "1 000+ API de données et Tools MCP · utilise les crédits Flatkey",
"ct.li": "Suivez-nous sur LinkedIn",
"cp.badge": "NOUVEAU · flatkey Compute · en ligne",
"cp.h1": "Tout votre compute,<br>une seule clé<span class=\"dot\">.</span>",
"cp.sub": "Louez des GPU entiers à l'heure et connectez-vous en SSH, déployez n'importe quel modèle en API au token et générez de la vidéo à la seconde — en self-service, depuis une seule clé flatkey et un seul solde. En ligne dès maintenant, sans liste d'attente. Nous ne stockons pas de cartes, donc le prix reste au plancher du marché.",
"cp.cta1": "Ouvrir Compute — c'est en ligne →",
"cp.cta2": "Parler aux ventes",
"cp.a1": "RTX 4090 à partir de $0.72/hr",
"cp.a2": "SSH & Jupyter",
"cp.a3": "Modèles au token",
"cp.a4": "Vidéo à la seconde",
"cp.a5": "Une clé · un solde",
"cp.s1eye": "Le manque",
"cp.s1h": "Le marché du compute est saturé. La boucle, non.",
"cp.s1p": "Cinq acteurs dominent le marché du GPU brut : Vast (le spot le moins cher), RunPod (self-service), Lambda (entraînement), Together (stack logiciel), CoreWeave (clusters privés). Aucun ne ferme la boucle qui compte : modèles, GPU et vidéo sur une seule clé, un seul solde, avec un chemin en un clic de l'usage au token vers un endpoint dédié réservé, mono-locataire et couvert par un SLA. flatkey a déjà les modèles, la facturation et les utilisateurs — et Compute est en ligne : louez un GPU, déployez un modèle ou générez de la vidéo dès aujourd'hui, puis faites passer vos modèles populaires en dédié quand vous montez en charge.",
"cp.s2eye": "Comment ça marche",
"cp.s2h": "Louez, déployez ou générez — en self-service",
"cp.f1b": "Louer un GPU",
"cp.f1s": "Carte entière à l'heure, connexion SSH et Jupyter",
"cp.f2b": "Déployer un modèle",
"cp.f2s": "N'importe quel modèle en API, au token",
"cp.f3b": "Générer de la vidéo",
"cp.f3s": "À la seconde, en marque blanche",
"cp.f4b": "Un seul solde",
"cp.f4s": "Tout est facturé depuis votre portefeuille flatkey",
"cp.f5b": "Passez au dédié",
"cp.f5s": "Faites passer les modèles populaires vers des endpoints réservés avec SLA",
"cp.s3eye": "Pourquoi flatkey",
"cp.s3h": "Pas un cloud GPU de plus",
"cp.c1t": "Léger en actifs — l'OpenRouter du compute",
"cp.c1p": "Nous n'achetons pas de cartes et ne portons pas le capex. Nous agrégeons l'offre et routons vers le prix plancher, puis l'enveloppons dans un point d'entrée entreprise unique avec SLA. Moins cher que posséder, plus stable que le spot brut.",
"cp.c2t": "Inférence ↔ compute, boucle fermée",
"cp.c2p": "Vos modèles, votre facturation et votre équipe vivent déjà ici. Passer de « utiliser un modèle » à « réserver sa capacité » se fait sans friction — et une seule facture au lieu de deux fournisseurs.",
"cp.c3t": "Flotte Apple Silicon grande mémoire",
"cp.c3p": "Une machine à 512GB de mémoire unifiée exécute un modèle 671B sur un seul nœud, plus une flotte mondiale Apple Silicon. Une inférence à grande mémoire et économe en énergie qu'aucun cloud purement NVIDIA ne peut égaler.",
"cp.c4t": "Niveau entreprise, facturation unifiée",
"cp.c4p": "Isolation privée, budgets et quotas par équipe, spend API, et un objectif de SLA public — inférence et compute sur une seule facture que votre équipe finance peut réellement rapprocher.",
"cp.s4eye": "Ancre de prix",
"cp.s4h": "Au prix plancher du marché",
"cp.tmodel": "Modèle",
"cp.tm1": "Clusters privés",
"cp.tm2": "Cluster à la demande",
"cp.tm3": "À la demande",
"cp.tm4": "Instance / bare-metal",
"cp.tm5": "Déployez votre propre app",
"cp.tm6a": "à partir de $1.79/hr",
"cp.tm6b": "à partir de $0.99/hr",
"cp.tm6c": "Self-service + dédié + SLA",
"cp.note": "En self-service dès aujourd'hui : louez une RTX 4090 à partir de $0.72/hr avec SSH, ou exécutez des modèles au token et de la vidéo à la seconde — le tout depuis un seul solde. L'offre backend est sourcée par le prix sur des marketplaces agrégées, si bien qu'un endpoint H100 dédié reste sous Lambda / CoreWeave / Novita à la demande, tout en ajoutant un SLA entreprise, une isolation privée et une facturation unifiée que le spot brut ne peut offrir. La marge vient du routage et de la mesure, pas du portage de matériel inactif. Les prix d'ancrage reflètent les tarifs publics au 2026-07-17 ; les tarifs self-service sont indicatifs et affichés en direct dans la console.",
"cp.s5eye": "Pour qui",
"cp.s5h": "Conçu pour les équipes qui font de l'inférence à grande échelle",
"cp.w1t": "Entreprises d'agents et d'apps IA",
"cp.w1p": "Quelques modèles portent l'essentiel de votre trafic. Réservez-leur une capacité dédiée au prix plancher, sans quitter la plateforme sur laquelle vous facturez déjà.",
"cp.w2t": "Déploiement privé et conformité",
"cp.w2p": "Amenez votre propre modèle ou fine-tune, hébergez-le en isolation privée, et routez-le via vos clés et quotas existants.",
"cp.leadh": "Besoin de capacité dédiée ou d'un déploiement privé ?",
"cp.leadsub": "Le self-service est en ligne dans la console — commencez quand vous voulez. Pour un endpoint réservé mono-locataire, une isolation privée ou un devis au volume, dites-nous ce que vous exécutez et nous reviendrons avec des chiffres. English / 中文 tous deux acceptés.",
