"cp.mini": "Vous préférez l'asynchrone ? <a href=\"mailto:support@flatkey.ai\" style=\"color:var(--violet-deep);font-weight:650\">support@flatkey.ai</a> · <a href=\"https://discord.gg/VrbZFDXj5g\" style=\"color:var(--violet-deep);font-weight:650\">Discord</a><br>Accès anticipé — le compute dédié est déployé d'abord auprès des partenaires de conception.",
