"tu.p1": "Les 100+ modèles avec jusqu'à $45/mois d'usage, plus 300 media credits pour l'image et la vidéo. 10 requêtes/min. Annulable à tout moment.",
"tu.p2": "Jusqu'à $90/mois d'usage, 1 200 media credits et 30 requêtes/min. Pour le code quotidien et la production.",
