"d.h1": "Construisez avec flatkey",
"d.hp": "Passerelle de modèles officiels. Une clé route vers 100+ endpoints réels — texte, vidéo, audio — avec un SLA contractuel derrière chaque appel.",
"d.search": "Cherchez dans la doc, ou posez une question…",
"d.st1": "SLA SIGNÉ · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">CONDITIONS</a>",
"d.st2": "TOKENS / MOIS",
"d.st3": "MODÈLES OFFICIELS",
"d.st4": "PROTOCOLES : OPENAI + ANTHROPIC",
"d.card1p": "Endpoint compatible OpenAI sur router.flatkey.ai/v1. Changez le base_url, gardez votre SDK — chat, tools, streaming, sortie structurée.",
"d.card2p": "Forme native de l'API Anthropic — pointez Claude Code ou Cline vers le même base URL avec votre key sk-fk-…. Sans couche de traduction.",
"d.card3h": "Modèles média",
"d.card3p": "Vidéo Seedance 2.5, voix temps réel, TTS et transcription — à la seconde ou au caractère, sur le même solde.",
"d.card4h": "Gouvernance d'équipe",
"d.card4p": "Une key par membre avec plafonds et allowlists ; registre par requête, quotas et API de dépense pour la finance.",
"d.qsh": "Commencez par un appel",
"d.qsp": "La plupart commencent ici : créez une key dans la console, changez le base_url, envoyez une requête. Trois lignes, zéro infrastructure.",
"d.llm": "Vous construisez avec un agent IA ? Récupérez l'index complet sur <a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a> — chaque page a un miroir markdown (.md).",
"d.gh": "Guides — les quatre questions que tout le monde pose",
"d.c1k": "CODING AGENTS · CODEX CLI",
"d.c1h": "Connecter Codex",
"d.c1s1": "Une ligne : <span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> puis choisissez <code>Codex CLI</code>.",
"d.c1s2": "Manuel : dans Codex, choisissez <b>API key login</b>, base URL <code>https://router.flatkey.ai/v1</code>, collez votre key <code>sk-fk-…</code>.",
"d.c1s3": "Un groupe renvoie 503 ? Basculez la key vers un autre groupe dans l'éditeur (voir Groupes et routage).",
"d.c2k": "CODING AGENTS · PROTOCOLE ANTHROPIC",
"d.c2h": "Connecter Claude Code / Cline",
"d.c2s1": "Deux variables d'environnement :<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows : <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "Ou persistez dans <code>~/.claude/settings.json</code> :<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "Lancez <code>claude</code> normalement. Cline : fournisseur <b>Anthropic</b>, même base URL + key.",
"d.c3k": "ÉQUIPES · KEYS, GROUPES ET QUOTAS",
"d.c3h": "Une key par personne, un plafond par key",
"d.c3s1": "Créez une key par coéquipier dans <b>Console → API Keys</b> ; fixez un <code>plafond</code> mensuel et une allowlist optionnelle par key.",
"d.c3s2": "<b>Les groupes choisissent le pool de routage, pas la personne</b> : <code>Standard</code> = canaux officiels agrégés (défaut) ; <code>Economy</code> = ligne dédiée la moins chère. Une key appartient à un groupe, déplaçable à tout moment.",
"d.c3s3": "Dépense par key, tokens par type, quota restant : <b>Usage &amp; Logs</b> ou l'API registre.",
"d.c4k": "FACTURATION · PRIX ET CACHE, EN CLAIR",
"d.c4h": "Ce que veut dire chaque chiffre",
"d.tblh": "<th>PRIX</th><th>SIGNIFICATION</th>",
"d.tbl1": "par 1M de tokens de prompt envoyés",
"d.tbl2": "par 1M de tokens générés",
"d.tbl3": "tokens de préfixe renvoyés, ~10% du prix d'entrée · cache 5–60 min selon le lab",
"d.c4s1": "<b>Santé 30 jours</b> = % de requêtes réussies sur 30 jours, trafic réel.",
"d.c4s2": "Les requêtes échouées (5xx) ne sont jamais facturées ; le failover facture le modèle qui a répondu. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA complet →</a>",
"d.cmh": "Communauté",
"d.cmp": "Des builders qui répondent aux builders — configs de routage, setups d'agents, choix de modèles. L'équipe lit tout ; gateway-bench et l'audit log sont développés en public.",
"st.kick": "STATUT API · MIS À JOUR TOUTES LES 60 SECONDES", "st2.kick": "STATUT API · PAGE DE STATUT PUBLIQUE", "st2.h2": "La disponibilité, en toute transparence.", "st2.sub": "Objectif SLA 99,5% · 90 jours d’uptime et historique des incidents sur la <a href=\"/status\">page de statut publique →</a>", "st2.live": "en direct →", "st2.more": "Voir le statut complet et l’historique des incidents →",
"st.ok": "Tous les systèmes opérationnels",
"st.slaline": "Objectif SLA 99,5% · <a href=\"sla.html\" style=\"color:#fff\">lire le SLA public →</a>",
"st.inch": "Historique des incidents",
"st.sub": "S'abonner",
"st.i1": "<b>Résolu — latence élevée sur un canal GPT.</b> Trafic rebasculé automatiquement en quelques secondes ; requêtes échouées non facturées.",
"st.i2": "<b>Terminé — maintenance base de données planifiée.</b> Les endpoints d'inférence ont fonctionné normalement.",
"st.i3": "<b>Aucun incident ces 7 derniers jours.</b>",
"st.ago": "il y a 90 jours",
"st.today": "Aujourd'hui",
