"hero.h1": "Une clé<br><span class=\"price\">Plus de modèles<span class=\"toolLine\"> Plus outils</span><span class=\"costLine\">Coûts réduits</span></span>",
"hero.sub": "Un seul solde couvre plus de 100 modèles officiels et plus de 1000 outils facturés par appel Sans sièges inutilisés sans abonnements en double ni API Keys dispersées chez les fournisseurs",
