"hero.invoice": "Tous les modèles et outils Une seule facture",
"hero.cta1": "Recevez jusqu'à 40 $ de crédits gratuits",
"hero.cta2": "Liste des modèles",
"hero.proof": "<b class=\"num\">46B</b> tokens/mois · <b class=\"num\">4K+</b> utilisateurs payants · <b class=\"num\">100+</b> entreprises en production · <b class=\"num\">0</b> modèle échangé — <a href=\"/status\" style=\"color:var(--violet-deep);font-weight:600\">journal d'audit public ↗</a>",
"board.foot": "Voir les 100+ modèles et leur santé en direct →",
"proof.t1": "DÉPART GRATUIT",
"proof.h1": "$1 de crédit + <span>3 essais avant inscription</span>",
"proof.p1": "Together et Segmind ont supprimé leurs offres gratuites ; Novita est à $0.50. flatkey vous laisse tester de vrais modèles avant même de vous connecter.",
"proof.t2": "ROUTAGE INTELLIGENT",
"proof.h2": "flatkey-auto, <span>sans frais de routage</span>",
"proof.p2": "Un seul nom de modèle ; la gateway choisit le meilleur modèle officiel par requête — selon la tâche et la santé, toujours au multiplicateur le plus bas.",
"proof.t3": "CONFIANCE · ZÉRO QUANTIFICATION",
"proof.h3": "APIs officielles, <span>auditées chaque heure</span>",
"proof.p3": "Pas de re-service fp8, pas d'échange silencieux. Chaque modèle est sondé contre son empreinte officielle, sur un journal public — 100+ modèles, chaque heure.",
"proof.t4": "PAYEZ EN LOCAL",
"proof.h4": "Pix, UPI, Alipay — <span>votre devise</span>",
"proof.p4": "Prix en BRL, INR ou CNY au paiement, sécurisé 3DS. Plus une API compatible Anthropic : pointez Claude Code ou Cline vers un base_url.",
"cmp.h2": "Claude à 67 % du tarif officiel.<br>Les autres facturent plein tarif.",
"cmp.sub": "Claude Opus 4.8, $ par 1M de tokens d'entrée, mesuré le 2026-07-14.",
"cmp.foot": "Together, Novita et Segmind ne vendent même pas Claude officiel. flatkey : Claude à ⅔ du tarif officiel — un abonnement, tous les modèles ; l'enterprise encore moins cher.",
"trust.kick": "CONFIANCE · SONDES HORAIRES D'AUTHENTICITÉ",
"trust.h2": "0 modèle échangé. <em>Jamais.</em><br>Et nous le prouvons.",
"trust.p": "Chaque heure, chaque modèle est sondé contre son empreinte officielle — logits, tokenizer, forme de refus. Le journal est public. Les autres demandent la confiance ; flatkey montre les reçus.",
"compl.kick": "CONFORMITÉ · AUDITABILITÉ ENTREPRISE",
"compl.h2": "Chaque token,<br>au registre<em>.</em>",
"compl.p": "Grand livre par requête : tokens d'entrée, de sortie et en cache — exportable, accessible par API. Factures sous 48h, paiements 3DS, plafonds par sous-clé, listes de modèles autorisés.",
"mdl.kick": "MODÈLES · 100+ OFFICIELS, UNE CLÉ",
"mdl.h2": "Chaque grand laboratoire<em>.</em><br>Une clé.",
"mdl.p": "OpenAI, Anthropic, Google, DeepSeek, Alibaba, Zhipu, Moonshot, ByteDance… les nouveaux modèles arrivent sous 24h — toujours les vrais endpoints.",
"mdl.cta1": "Commencer — $1 offerts",
