"cp.h1": "Todo o seu compute,<br>uma só key<span class=\"dot\">.</span>",
"cp.sub": "Alugue GPUs inteiras por hora e entre por SSH, faça deploy de qualquer modelo como API por token e gere vídeo por segundo — self-service, a partir de uma única key da flatkey e um só saldo. No ar agora, sem lista de espera. Não estocamos placas, então o preço fica no piso do mercado.",
