"cp.a3": "Modelos por token",
"cp.a4": "Vídeo por segundo",
"cp.a5": "Uma key · um saldo",
"cp.s1eye": "A lacuna",
"cp.s1h": "O mercado de compute está lotado. O ciclo, não.",
"cp.s1p": "Cinco players dominam o mercado de GPU bruta — Vast (o spot mais barato), RunPod (self-service), Lambda (treinamento), Together (stack de software), CoreWeave (clusters privados). Nenhum fecha o ciclo que importa: modelos, GPUs e vídeo em uma só key, um só saldo, com um caminho de um clique do uso por token até um endpoint dedicado reservado, de inquilino único e com SLA. A flatkey já tem os modelos, o faturamento e os usuários — e o Compute está no ar: alugue uma GPU, faça deploy de um modelo ou gere vídeo hoje, e depois promova os modelos populares para dedicado quando escalar.",
"cp.s2eye": "Como funciona",
"cp.s2h": "Alugue, faça deploy ou gere — self-service",
"cp.f1b": "Alugue uma GPU",
"cp.f1s": "Placa inteira por hora, entre por SSH e Jupyter",
"cp.f2b": "Faça deploy de um modelo",
"cp.f2s": "Qualquer modelo como API, por token",
"cp.f3b": "Gere vídeo",
"cp.f3s": "Por segundo, marca branca",
"cp.f4b": "Um só saldo",
"cp.f4s": "Tudo é cobrado da sua carteira flatkey",
"cp.f5b": "Escale para dedicado",
"cp.f5s": "Promova os modelos populares para endpoints reservados com SLA",
"cp.s3eye": "Por que a flatkey",
"cp.s3h": "Não é mais uma nuvem de GPU",
"cp.c1t": "Asset-light — o OpenRouter do compute",
"cp.c1p": "Não compramos placas nem carregamos o capex. Agregamos a oferta e roteamos para o menor preço, depois embalamos tudo em um único ponto de entrada empresarial com SLA. Mais barato que ter, mais estável que o spot bruto.",
"cp.c2t": "Inferência ↔ compute, ciclo fechado",
"cp.c2p": "Seus modelos, faturamento e equipe já vivem aqui. Ir de \"usar um modelo\" para \"reservar sua capacidade\" tem zero atrito — e uma fatura em vez de dois fornecedores.",
"cp.c3t": "Frota Apple Silicon de alta memória",
"cp.c3p": "Uma máquina de 512GB de memória unificada roda um modelo de 671B em um único nó, além de uma frota global de Apple Silicon. Inferência de alta memória e eficiência energética que nenhuma nuvem puramente NVIDIA consegue igualar.",
"cp.c4t": "Nível empresarial, faturamento unificado",
"cp.c4p": "Isolamento privado, orçamentos e cotas por equipe, spend API e uma meta pública de SLA — inferência e compute em uma única fatura que seu time financeiro consegue de fato conciliar.",
"cp.s4eye": "Âncora de preço",
"cp.s4h": "Precificado no piso do mercado",
"cp.tmodel": "Modelo",
"cp.tm1": "Clusters privados",
