"cp.tm6a": "a partir de $1.79/hr",
"cp.tm6b": "a partir de $0.99/hr",
"cp.tm6c": "Self-service + dedicado + SLA",
"cp.note": "Self-service a partir de hoje: alugue uma RTX 4090 a partir de $0.72/hr com SSH, ou rode modelos por token e vídeo por segundo — tudo a partir de um só saldo. A oferta de backend é obtida por preço em marketplaces agregados, então um endpoint H100 dedicado continua ficando abaixo de Lambda / CoreWeave / Novita sob demanda, adicionando SLA empresarial, isolamento privado e faturamento unificado que o spot bruto não oferece. A margem vem do roteamento e da medição, não de carregar hardware ocioso. Os preços âncora refletem tarifas públicas em 2026-07-17; as tarifas de self-service são indicativas e exibidas ao vivo no console.",
"cp.s5eye": "Para quem é",
"cp.s5h": "Feito para equipes que rodam inferência em escala",
"cp.w1t": "Empresas de agentes e apps de IA",
"cp.w1p": "Poucos modelos carregam a maior parte do seu tráfego. Reserve capacidade dedicada para eles a preço de piso, sem sair da plataforma pela qual você já fatura.",
"cp.w2t": "Implantação privada e conformidade",
"cp.w2p": "Traga seu próprio modelo ou fine-tune, hospede-o em isolamento privado e roteie-o pelas suas chaves e cotas existentes.",
"cp.leadh": "Precisa de capacidade dedicada ou deploy privado?",
"cp.leadsub": "O self-service já está no ar no console — comece quando quiser. Para um endpoint reservado de inquilino único, isolamento privado ou uma cotação por volume, conte o que você está rodando e voltaremos com números. English / 中文 ambos servem.",
