"tu.faqh": "FAQ de preços",
"tu.q1": "O que um plano inclui?",
"tu.a1": "Uma franquia mensal de uso — até $45 no Go, $90 no Pro, $300 no Max — válida em todos os 100+ modelos, mais media credits para gerar imagem e vídeo. Janelas curtas de 5 horas e 7 dias mantêm o serviço rápido para todos.",
"tu.q2": "É assinatura mensal?",
"tu.a2": "O pagamento por uso não tem assinatura nem expiração. Go, Pro e Max renovam mensalmente e podem ser cancelados a qualquer momento; após a franquia mensal, a mesma key continua usando seu saldo por uso.",
"tu.q3": "Quais modelos um plano cobre?",
"tu.a3": "Todo plano cobre GPT, Claude, Gemini, DeepSeek e os modelos de imagem, áudio e vídeo — por um gateway compatível com OpenAI.",
"tu.q4": "Posso ver como o saldo é consumido?",
"tu.a4": "Sim. O uso é medido por modelo, tipo de token e logs de requisição para revisar gasto e controlar custo.",
"tu.q5": "Quando escolher Enterprise?",
"tu.a5": "Para uso mensal maior, faturamento, compras, descontos de roteamento sob medida ou controles de time.",
