"s.h1": "Um SLA para levar<br>ao setor de compras.",
"s.sub": "Não é promessa de vendas: documento público com meta de disponibilidade, método de medição e processo de incidentes definido. Contratos enterprise adicionam créditos contratuais e meta maior.",
