"s.cta2": "Texto legal completo ↗",
"s.cta3": "SLA Enterprise",
"s.big.k": "COMPROMISSO MENSAL DE DISPONIBILIDADE",
"s.big.p": "Medido nos serviços cobertos — API do router, endpoint Anthropic, console e medição — pelos nossos monitores de produção, por mês-calendário. Planos enterprise: 99,9% com roteamento prioritário.",
"s.p1k": "FAILOVER",
"s.p1h": "5 classes de canal, automático",
"s.p1p": "Cada modelo é servido por até cinco classes de canal upstream. Checagens de saúde rodam continuamente; se um canal degrada, as requisições vão para o próximo melhor canal oficial com retries automáticos.",
"s.p2k": "MEDIÇÃO JUSTA",
"s.p2h": "Erros não consomem saldo",
"s.p2p": "A cobrança liquida sobre tokens confirmados após a resposta; erros retornados pela própria flatkey nunca consomem saldo. Um failover cobra só o modelo que respondeu.",
"s.p3k": "TRANSPARÊNCIA",
"s.p3h": "Você pode verificar tudo",
"s.p3p": "A <a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">página de status</a> mostra 90 dias de uptime por componente; cada modelo mostra a taxa de sucesso de 30 dias com tráfego real. Sem números sintéticos.",
"s.credh": "Créditos de serviço — acordos enterprise",
"s.credp": "Nos termos padrão, a remediação é caso a caso conforme o SLA público. Acordos enterprise definem uma tabela contratual de créditos — estrutura típica:",
"s.tblh": "<th>DISPONIBILIDADE MENSAL</th><th>CRÉDITO</th><th>COMO CHEGA</th>",
"s.row12": "creditado ao saldo em 5 dias úteis após aprovação",
"s.row3": "100% do uso do mês creditado",
"s.fine": "Créditos aplicam-se ao uso do serviço coberto no mês afetado. Pedidos: email para support@flatkey.ai em 30 dias com request IDs ou timestamps; nossos registros de monitoramento são a fonte de medição. Exclusões conforme o texto legal: quedas de laboratórios além do alcance do failover, manutenção programada com aviso, força maior e erros de configuração do cliente.",
"s.clmh": "Como funciona um pedido",
"s.st1b": "Detecte",
"s.st1p": "Veja a degradação na página de status ou nos seus logs. Anote request IDs ou a janela de tempo.",
"s.st2b": "Registre",
