"d.c1s2": "Manual: no Codex escolha <b>API key login</b>, base URL <code>https://router.flatkey.ai/v1</code>, cole sua key <code>sk-fk-…</code>.",
"d.c1s3": "Grupo retornando 503? Mova a key para outro grupo no editor (veja Grupos e roteamento).",
"d.c2k": "CODING AGENTS · PROTOCOLO ANTHROPIC",
"d.c2h": "Conectar Claude Code / Cline",
"d.c2s1": "Duas variáveis de ambiente:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows: <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "Ou persista em <code>~/.claude/settings.json</code>:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "Rode <code>claude</code> normalmente. Cline: provedor <b>Anthropic</b>, mesmo base URL + key.",
"d.c3k": "TIMES · KEYS, GRUPOS E COTAS",
"d.c3h": "Uma key por pessoa, um limite por key",
"d.c3s1": "Crie uma key por colega em <b>Console → API Keys</b>; defina um <code>limite</code> mensal e allowlist opcional por key.",
"d.c3s2": "<b>Grupos escolhem o pool de roteamento, não a pessoa</b>: <code>Standard</code> = canais oficiais agregados (padrão); <code>Economy</code> = linha dedicada mais barata. Uma key pertence a um grupo e pode ser movida.",
"d.c3s3": "Gasto por key, tokens por tipo e cota restante: <b>Usage &amp; Logs</b> ou a API de razão.",
"d.c4k": "COBRANÇA · PREÇOS E CACHE, SEM RODEIOS",
"d.c4h": "O que cada número significa",
"d.tblh": "<th>PREÇO</th><th>SIGNIFICADO</th>",
"d.tbl1": "por 1M de tokens de prompt enviados",
"d.tbl2": "por 1M de tokens gerados",
"d.tbl3": "tokens de prefixo reenviados, ~10% do preço de input · cache de 5–60 min por lab",
"d.c4s1": "<b>Saúde 30 dias</b> = % de requisições bem-sucedidas nos últimos 30 dias, tráfego real.",
"d.c4s2": "Requisições falhas (5xx) nunca são cobradas; o failover cobra só o modelo que respondeu. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA completo →</a>",
"d.cmh": "Comunidade",
"d.cmp": "Builders respondendo builders — configs de roteamento, setups de agentes, escolha de modelos. O time lê tudo; gateway-bench e o audit log são desenvolvidos em aberto.",
"st.kick": "STATUS DA API · ATUALIZADO A CADA 60 SEGUNDOS", "st2.kick": "STATUS DA API · PÁGINA PÚBLICA DE STATUS", "st2.h2": "Disponibilidade, às claras.", "st2.sub": "Meta de SLA 99,5% · 90 dias de uptime e histórico de incidentes na <a href=\"/status\">página pública de status →</a>", "st2.live": "ao vivo →", "st2.more": "Ver status completo e histórico de incidentes →",
"st.ok": "Todos os sistemas operacionais",
"st.slaline": "Meta de SLA 99,5% · <a href=\"sla.html\" style=\"color:#fff\">ler o SLA público →</a>",
"st.inch": "Histórico de incidentes",
"st.sub": "Assinar atualizações",
"st.i1": "<b>Resolvido — latência elevada em um canal GPT.</b> Tráfego redirecionado automaticamente em segundos; requisições falhas não cobradas.",
"st.i2": "<b>Concluído — manutenção programada de banco de dados.</b> Endpoints de inferência funcionaram normalmente.",
"st.i3": "<b>Sem incidentes nos últimos 7 dias.</b>",
"st.ago": "há 90 dias",
"st.today": "Hoje",
