"proof.h4": "Pix, UPI, Alipay — <span>sua moeda</span>",
"proof.p4": "Preços em BRL, INR ou CNY no checkout, com 3DS. E API compatível com Anthropic: aponte o Claude Code ou Cline para um base_url e pronto.",
"cmp.h2": "Claude a 67% do preço oficial.<br>Os outros cobram preço cheio.",
"cmp.sub": "Claude Opus 4.8, $ por 1M de tokens de entrada, medido em 2026-07-14.",
"cmp.foot": "Together, Novita e Segmind nem vendem Claude oficial. flatkey: Claude a ⅔ do preço oficial — uma assinatura, todos os modelos; enterprise ainda mais barato.",
"trust.kick": "CONFIANÇA · SONDAS HORÁRIAS DE AUTENTICIDADE",
"trust.h2": "0 modelos trocados. <em>Nunca.</em><br>E nós provamos.",
"trust.p": "A cada hora, cada modelo é sondado contra sua impressão oficial — logits, tokenizer, padrão de recusa. O log é público. Os baratos pedem confiança; a flatkey mostra recibos.",
