"cp.h1": "Все ваши вычисления,<br>один ключ<span class=\"dot\">.</span>",
"cp.sub": "Арендуйте целые GPU с почасовой оплатой и подключайтесь по SSH, разворачивайте любую модель как API с оплатой по токенам и генерируйте видео посекундно — самообслуживание, с одним ключом flatkey и одним балансом. Уже доступно, без листа ожидания. Мы не копим карты, поэтому цена держится на минимуме рынка.",
