"cp.s1h": "Рынок вычислений переполнен. А цикл — нет.",
"cp.s1p": "Пять игроков владеют рынком «голых» GPU — Vast (самый дешёвый spot), RunPod (self-serve), Lambda (обучение), Together (программный стек), CoreWeave (частные кластеры). Ни один из них не замыкает главный цикл: модели, GPU и видео на одном ключе, одном балансе, с переходом в один клик от оплаты по токенам к зарезервированному, однопользовательскому, обеспеченному SLA выделенному endpoint. У flatkey уже есть модели, биллинг и пользователи — и Compute уже доступен: арендуйте GPU, разверните модель или сгенерируйте видео сегодня, а затем переводите популярные модели в выделенные, когда масштабируетесь.",
"cp.s2eye": "Как это работает",
"cp.s2h": "Арендуйте, разворачивайте или генерируйте — самообслуживание",
"cp.f1b": "Арендуйте GPU",
