"cp.s3eye": "Почему flatkey",
"cp.s3h": "Не очередное GPU-облако",
"cp.c1t": "Без тяжёлых активов — OpenRouter для вычислений",
"cp.c1p": "Мы не покупаем карты и не несём капзатрат. Мы агрегируем предложение и маршрутизируем к минимальной цене, а затем оборачиваем всё в единую корпоративную точку входа с SLA. Дешевле, чем владеть, стабильнее, чем «голый» spot.",
"cp.c2t": "Инференс ↔ вычисления, замкнутый цикл",
"cp.c2p": "Ваши модели, биллинг и команда уже здесь. Переход от «использовать модель» к «зарезервировать её мощность» — без трения, и один счёт вместо двух поставщиков.",
"cp.c3t": "Флот Apple Silicon с большой памятью",
"cp.c3p": "Машина с 512GB унифицированной памяти запускает модель на 671B на одном узле, плюс глобальный флот Apple Silicon. Инференс с большой памятью и энергоэффективностью, недостижимый ни для одного чисто NVIDIA-облака.",
"cp.c4t": "Корпоративный уровень, единый биллинг",
