"cp.tm6c": "Self-serve + выделенный + SLA",
"cp.note": "Самообслуживание уже сегодня: арендуйте RTX 4090 от $0.72/hr с SSH или запускайте модели по токенам и видео посекундно — всё с одного баланса. Предложение бэкенда закупается по цене на агрегированных маркетплейсах, поэтому выделенный H100-endpoint по-прежнему оказывается ниже Lambda / CoreWeave / Novita по требованию, добавляя корпоративный SLA, приватную изоляцию и единый биллинг, которых «голый» spot дать не может. Маржа идёт от маршрутизации и учёта, а не от простаивающего железа. Якорные цены отражают публичные тарифы на 2026-07-17; ставки самообслуживания ориентировочны и показываются в реальном времени в консоли.",
"cp.s5eye": "Кому это подходит",
"cp.s5h": "Создано для команд, запускающих инференс в масштабе",
"cp.w1t": "Компании агентов и AI-приложений",
"cp.w1p": "Несколько моделей несут большую часть вашего трафика. Зарезервируйте для них выделенную мощность по минимальной цене, не покидая платформу, через которую вы уже платите.",
