"cp.w2p": "Принесите свою модель или fine-tune, разместите её в приватной изоляции и маршрутизируйте через существующие ключи и квоты.",
"cp.leadh": "Нужна выделенная мощность или приватное развёртывание?",
"cp.leadsub": "Самообслуживание уже доступно в консоли — начните в любой момент. Для зарезервированного однопользовательского endpoint, приватной изоляции или расчёта по объёму расскажите, что вы запускаете, и мы вернёмся с цифрами. English / 中文 оба подойдут.",
