"tu.faqh": "FAQ по ценам",
"tu.q1": "Что входит в план?",
"tu.a1": "Месячный лимит использования — до $45 на Go, $90 на Pro, $300 на Max — на все 100+ моделей, плюс media credits для генерации изображений и видео. Короткие окна на 5 часов и 7 дней сохраняют сервис быстрым для всех.",
