"tu.a2": "Оплата по мере использования не требует подписки, а баланс не сгорает. Go, Pro и Max продлеваются ежемесячно и отменяются в любой момент; после месячного лимита тот же ключ использует ваш баланс по факту.",
"tu.q3": "Какие модели покрывает план?",
"tu.a3": "Каждый план покрывает GPT, Claude, Gemini, DeepSeek и модели изображений, аудио и видео — через OpenAI-совместимый шлюз.",
