"why.c3p": "Укажите Codex, Claude Code, OpenClaw или любому агентскому CLI файл SKILL.md от Flatkey. Агент научится находить и вызывать 100+ официальных моделей и 1 000+ инструментов с оплатой за вызов по одному ключу.",
