"nav.sla": "SLA",
"s.kick": "SLA · ПУБЛИЧНАЯ ЦЕЛЬ · ENTERPRISE-КРЕДИТЫ",
"s.h1": "SLA, который можно<br>показать закупкам.",
"s.sub": "Не обещание продавца: публичный документ с целевой доступностью, методикой измерения и определённым процессом инцидентов. Enterprise-контракты добавляют договорную сетку кредитов и более высокую цель.",
"s.cta1": "Статус в реальном времени →",
"s.cta2": "Полный юридический текст ↗",
"s.cta3": "Enterprise SLA",
"s.big.k": "МЕСЯЧНОЕ ОБЯЗАТЕЛЬСТВО ПО ДОСТУПНОСТИ",
"s.big.p": "Измеряется по покрываемым сервисам — API роутера, Anthropic-эндпоинт, консоль и биллинг — нашим продакшен-мониторингом, за календарный месяц. Enterprise: 99,9% с приоритетной маршрутизацией.",
"s.p1k": "ОТКАЗОУСТОЙЧИВОСТЬ",
"s.p1h": "5 классов каналов, автоматически",
"s.p1p": "Каждая модель обслуживается до пяти классов каналов. Проверки здоровья идут непрерывно; при деградации канала запросы автоматически уходят на следующий лучший официальный канал с повторами.",
"s.p2k": "ЧЕСТНЫЙ УЧЁТ",
"s.p2h": "Ошибки не съедают баланс",
"s.p2p": "Списание происходит по подтверждённым токенам после ответа; ошибки самого flatkey никогда не расходуют баланс. Failover тарифицирует только ответившую модель.",
"s.p3k": "ПРОЗРАЧНОСТЬ",
"s.p3h": "Всё можно проверить самому",
"s.p3p": "<a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">Страница статуса</a> показывает аптайм за 90 дней по компонентам; каждая модель — успешность за 30 дней на реальном трафике. Никаких синтетических цифр.",
"s.credh": "Сервисные кредиты — enterprise-соглашения",
"s.credp": "По стандартным условиям возмещение рассматривается индивидуально согласно публичному SLA. Enterprise-соглашения фиксируют договорную сетку кредитов — типовая структура:",
"s.tblh": "<th>МЕСЯЧНАЯ ДОСТУПНОСТЬ</th><th>КРЕДИТ</th><th>КАК ПРИХОДИТ</th>",
"s.row12": "зачисляется на баланс в течение 5 рабочих дней после одобрения",
"s.row3": "возврат 100% использования за месяц",
"s.fine": "Кредиты применяются к использованию затронутого сервиса в затронутом месяце. Заявка: письмо на support@flatkey.ai в течение 30 дней с request ID или таймстампами; источником измерения служат записи нашего мониторинга. Исключения — по полному тексту: сбои лабораторий вне досягаемости failover, плановые работы с уведомлением, форс-мажор, ошибки конфигурации клиента.",
"s.clmh": "Как работает заявка",
"s.st1b": "Заметить",
"s.st1p": "Увидели деградацию на странице статуса или в своих логах — сохраните request ID или окно времени.",
"s.st2b": "Подать",
"s.st2p": "Письмо на support@flatkey.ai — тема «SLA claim», email аккаунта, затронутый эндпоинт, таймстампы. Ответ за 1 рабочий день.",
"s.st3b": "Получить кредит",
"s.st3p": "Сверяем с продакшен-мониторингом и зачисляем на баланс. Без споров с чат-ботом.",
"s.moreh": "Нужно больше 99,5%?",
"s.morep": "Enterprise-соглашения добавляют цель 99,9%, приоритетную маршрутизацию при инцидентах, выделенный канал поддержки (Slack или WeChat) и индивидуальные сетки кредитов — в контракте, а не на слайде.",
"s.morec1": "Связаться с продажами →",
