"d.st4": "ПРОТОКОЛЫ: OPENAI + ANTHROPIC",
"d.card1p": "OpenAI-совместимый эндпоинт router.flatkey.ai/v1. Меняете base_url, SDK остаётся — чат, инструменты, стриминг, структурированный вывод.",
