"d.c1h": "Подключить Codex",
"d.c1s1": "Одной строкой: <span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> и выберите <code>Codex CLI</code>.",
"d.c1s2": "Вручную: в Codex выберите <b>API key login</b>, base URL <code>https://router.flatkey.ai/v1</code>, вставьте ключ <code>sk-fk-…</code>.",
"d.c1s3": "Группа отдаёт 503? Переключите ключ на другую группу в редакторе (см. «Группы и маршрутизация»).",
