"d.c2s2": "Или сохраните в <code>~/.claude/settings.json</code>:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
