"d.c3h": "Один ключ на человека, один лимит на ключ",
"d.c3s1": "Создайте ключ каждому в <b>Console → API Keys</b>; задайте месячный <code>лимит</code> и allowlist моделей.",
"d.c3s2": "<b>Группа выбирает пул маршрутизации, а не человека</b>: <code>Standard</code> = агрегированные официальные каналы (по умолчанию); <code>Economy</code> = самая дешёвая выделенная линия. Ключ принадлежит одной группе, переключается в любой момент.",
"d.c3s3": "Расход по ключу, токены по типам, остаток квоты: <b>Usage &amp; Logs</b> или API реестра.",
"d.c4k": "БИЛЛИНГ · ЦЕНЫ И КЭШ ПО-ЧЕЛОВЕЧЕСКИ",
"d.c4h": "Что значит каждая цифра",
