"tu.q1": "プランには何が含まれますか?",
"tu.a1": "月々のモデル利用枠——Go は最大 $45、Pro は最大 $90、Max は最大 $300——を 100+ モデルすべてに使えます。加えて画像・動画生成用の media credits 付き。5 時間・7 日間の短期上限で全員が快適に使えます。",
