"nav.sla": "SLA",
"s.kick": "SLA · 公開目標 · エンタープライズ補償",
"s.h1": "調達部門に<br>そのまま出せる SLA。",
"s.sub": "営業トークではありません。可用性目標・測定方法・明確なインシデント対応プロセスを記した公開文書です。エンタープライズ契約では契約上のクレジット表とより高い目標を追加できます。",
"s.cta1": "ライブステータス →",
"s.cta2": "法的全文 ↗",
"s.cta3": "エンタープライズ SLA",
"s.big.k": "月間可用性コミットメント",
"s.big.p": "対象サービス(ルーター API、Anthropic エンドポイント、コンソール、計測)を当社の本番監視が暦月単位で測定。エンタープライズは 99.9%+優先ルーティング。",
"s.p1k": "フェイルオーバー",
"s.p1h": "5 系統のチャネル、自動切替",
"s.p1p": "各モデルは最大 5 系統の上流チャネルで提供。ヘルスチェックは常時稼働し、劣化を検知すると自動リトライで次善の公式チャネルへ切り替えます。",
"s.p2k": "公正な計測",
"s.p2h": "エラーは残高を消費しない",
"s.p2p": "課金は応答後に確定トークン数で精算。flatkey 自身が返すエラーは残高を消費しません。フェイルオーバー時は応答したモデルのみ課金。",
"s.p3k": "透明性",
"s.p3h": "すべて自分で検証可能",
"s.p3p": "<a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">ステータスページ</a> にコンポーネント別 90 日稼働率、各モデルに実トラフィック 30 日成功率を表示。合成値はありません。",
"s.credh": "サービスクレジット — エンタープライズ契約",
"s.credp": "標準条件では公開 SLA に基づき個別に対応します。エンタープライズ契約では契約上のクレジット表を定義します——典型的な構成:",
"s.tblh": "<th>月間可用性</th><th>クレジット</th><th>返還方法</th>",
"s.row12": "承認後 5 営業日以内に残高へ返還",
"s.row3": "当月利用分を 100% 返還",
"s.fine": "クレジットは対象月の対象サービス利用分に適用。申請は 30 日以内に request ID またはタイムスタンプを添えて support@flatkey.ai へ。測定は当社本番監視の記録に基づきます。除外事項は法的全文に準拠:フェイルオーバーの及ばないモデル提供元の障害、事前告知済みメンテナンス、不可抗力、お客様側の設定起因の問題。",
"s.clmh": "申請の流れ",
"s.st1b": "検知",
"s.st1p": "ステータスページか自社ログで劣化を確認し、request ID か時間帯を控えます。",
"s.st2b": "申請",
"s.st2p": "support@flatkey.ai へメール — 件名「SLA claim」、アカウントメール、対象エンドポイント、タイムスタンプ。1 営業日以内に返信。",
"s.st3b": "返還",
"s.st3p": "本番監視と照合し、残高へクレジット。チャットボットと言い争う必要はありません。",
"s.moreh": "99.5% では足りない?",
"s.morep": "エンタープライズ契約では 99.9% 目標、障害時の優先ルーティング、専用サポートチャネル(Slack / WeChat)、カスタムクレジット表を追加——スライドではなく契約書に明記します。",
