"d.h1": "flatkey で作る",
"d.hp": "公式モデルゲートウェイ。1 つの key で 100+ の実ラボエンドポイントへ——テキスト・動画・音声。すべて契約 SLA 付き。",
"d.search": "ドキュメントを検索、または何でも質問…",
"d.st1": "署名済み SLA · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">条項</a>",
"d.st2": "トークン / 月",
"d.st3": "公式モデル",
"d.st4": "プロトコル:OPENAI + ANTHROPIC",
"d.card1p": "router.flatkey.ai/v1 の OpenAI 互換エンドポイント。base_url を変えるだけ、SDK はそのまま——チャット、ツール、ストリーミング、構造化出力。",
"d.card2p": "ネイティブな Anthropic API 形式——Claude Code や Cline を同じ base URL に向け、sk-fk-… キーを使うだけ。変換レイヤーなし。",
"d.card3h": "メディアモデル",
"d.card3p": "Seedance 2.5 動画、リアルタイム音声、TTS、文字起こし——秒・文字単位課金、同じ残高で。",
"d.card4h": "チーム統制",
"d.card4p": "メンバーごとに 1 キー、上限とモデル許可リスト付き;リクエスト単位の台帳、クォータ、支出 API。",
"d.qsh": "1 回の呼び出しから",
"d.qsp": "ほとんどの人はここから:コンソールでキーを作成、base_url を変更、リクエスト送信。3 行、インフラ不要。",
"d.llm": "AI エージェントで構築中?<a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a> で全ドキュメント索引を取得——全ページに markdown ミラー(.md)あり。",
"d.gh": "ガイド — みんなが聞く 4 つのこと",
"d.c1k": "コーディングエージェント · CODEX CLI",
"d.c1h": "Codex を接続",
"d.c1s1": "ワンライナー:<span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> インストーラーで <code>Codex CLI</code> を選択。",
"d.c1s2": "手動:Codex で <b>API key ログイン</b>を選び、base URL に <code>https://router.flatkey.ai/v1</code>、<code>sk-fk-…</code> キーを貼り付け。",
"d.c1s3": "グループが 503 を返す?キーエディタで別グループへ切替(下記「グループとルーティング」参照)。",
"d.c2k": "コーディングエージェント · ANTHROPIC プロトコル",
"d.c2h": "Claude Code / Cline を接続",
"d.c2s1": "環境変数を 2 つ:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows は <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "または <code>~/.claude/settings.json</code> に永続化:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "あとは通常どおり <code>claude</code> を実行。Cline はプロバイダー <b>Anthropic</b>、同じ base URL + キー。",
"d.c3k": "チーム · キー、グループ、上限",
"d.c3h": "1 人 1 キー、1 キー 1 上限",
"d.c3s1": "<b>Console → API Keys</b> でメンバーごとにキーを作成;キー単位で月間<code>上限</code>とモデル許可リストを設定。",
"d.c3s2": "<b>グループはルーティングプールを決めるもの</b>:<code>Standard</code> = 公式チャネル集約(デフォルト);<code>Economy</code> = 最安専用線。キーは 1 グループ所属、いつでも移動可。",
"d.c3s3": "キー別支出、種別トークン、残クォータ:<b>Usage &amp; Logs</b> か台帳 API で。",
"d.c4k": "課金 · 価格とキャッシュをわかりやすく",
"d.c4h": "各数値の意味",
"d.tblh": "<th>価格</th><th>意味</th>",
"d.tbl1": "送信 prompt トークン 100 万あたり",
"d.tbl2": "生成トークン 100 万あたり",
"d.tbl3": "再送プレフィックストークン、入力価格の約 10% · キャッシュは各ラボ 5〜60 分",
"d.c4s1": "<b>30 日ヘルス</b> = 直近 30 日の実トラフィックにおけるリクエスト成功率。",
"d.c4s2": "失敗リクエスト(5xx)は課金なし;フェイルオーバー時は応答したモデルのみ課金。 <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA 全文 →</a>",
