"mo.aud": "Mô hình âm thanh",
"mo.audsub": "Giọng realtime, TTS và phiên âm — theo phút hoặc 1K ký tự",
"tu.p1": "Đủ 100+ model với tối đa $45/tháng mức dùng, kèm 300 media credits cho ảnh và video. 10 yêu cầu/phút. Hủy bất cứ lúc nào.",
"tu.p2": "Tối đa $90/tháng mức dùng model, 1.200 media credits và 30 yêu cầu/phút. Cho code hằng ngày và production.",
"tu.p3": "Tối đa $300/tháng mức dùng, 5.000 media credits, 60 yêu cầu/phút và ưu tiên giờ cao điểm. Cho agent nặng và đội nhóm.",
"tu.faqh": "FAQ giá",
"tu.q1": "Gói gồm những gì?",
"tu.a1": "Hạn mức dùng model hằng tháng — tối đa $45 với Go, $90 với Pro, $300 với Max — dùng được trên đủ 100+ model, kèm media credits để tạo ảnh và video. Cửa sổ ngắn 5 giờ và 7 ngày giữ dịch vụ nhanh cho mọi người.",
"tu.q2": "Có phải thuê bao tháng?",
"tu.a2": "Trả theo mức dùng không cần đăng ký gói và số dư không hết hạn. Go, Pro và Max gia hạn hằng tháng, hủy được bất cứ lúc nào; sau hạn mức tháng, cùng key sẽ tiếp tục dùng số dư trả theo mức dùng.",
"tu.q3": "Gói phủ những model nào?",
"tu.a3": "Mọi gói đều phủ GPT, Claude, Gemini, DeepSeek và mô hình ảnh, âm thanh, video — qua một gateway tương thích OpenAI.",
"tu.q4": "Xem được số dư tiêu thế nào không?",
"tu.a4": "Được. Mức dùng đo theo mô hình, loại token và nhật ký yêu cầu để đội rà soát chi tiêu.",
"tu.q5": "Khi nào nên chọn Enterprise?",
"tu.a5": "Khi dùng nhiều hằng tháng, cần hóa đơn, mua sắm, chiết khấu định tuyến riêng hoặc kiểm soát cấp đội.",
"uc.kick": "TRƯỜNG HỢP DÙNG · MỘT LỆNH NỐI CODING AGENT",
"uc.h1": "Agent lập trình của bạn,<br><span style=\"color:var(--violet)\">rẻ hơn 33–60% so với giá niêm yết</span>.",
"uc.sub": "Giữ nguyên CLI quen thuộc. Một trình cài đặt trỏ Codex, Claude Code hay Image Buddy vào flatkey — một số dư, chi tiêu rõ, SDK không đổi.",
"uc.c1h": "Codex, <span>rẻ hơn tới 33%</span>",
"uc.c1p": "Giữ flow Codex CLI tương thích OpenAI, định tuyến qua flatkey — phí đo thấp hơn, một số dư trả trước, chi tiêu rõ.",
"uc.c2h": "Claude Code, <span>flow như cũ, hóa đơn nhẹ hơn</span>",
"uc.c2p": "flatkey nói định dạng Anthropic gốc. Trỏ Claude Code vào một base_url — mọi phiên đều đi qua số dư trả trước của bạn.",
"uc.c3h": "Image Buddy, <span>media cũng chung số dư</span>",
"uc.c3p": "Key chạy mô hình văn bản cũng bao luôn tạo ảnh. Chi tiêu media vào cùng số dư và nhật ký.",
"ob.h2": "Key của bạn đã sẵn sàng. Chạy thử ngay.",
