"s.big.p": "Đo trên các dịch vụ được bảo đảm — API router, endpoint Anthropic, console và đo lường — bởi hệ thống giám sát production, theo tháng dương lịch. Gói enterprise: 99,9% kèm định tuyến ưu tiên.",
