"s.p3p": "<a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">Trang trạng thái</a> hiển thị uptime 90 ngày theo từng thành phần; mỗi mô hình hiển thị tỷ lệ thành công 30 ngày từ lưu lượng thật. Không có số liệu tổng hợp giả.",
"s.credh": "Tín dụng dịch vụ — hợp đồng enterprise",
"s.credp": "Theo điều khoản chuẩn, việc khắc phục xử lý từng trường hợp theo SLA công khai. Hợp đồng enterprise định nghĩa bảng tín dụng — cấu trúc điển hình:",
