"s.row3": "hoàn 100% mức dùng của tháng",
"s.fine": "Tín dụng áp dụng cho mức dùng của dịch vụ bị ảnh hưởng trong tháng bị ảnh hưởng. Yêu cầu: email support@flatkey.ai trong 30 ngày kèm request ID hoặc mốc thời gian; hồ sơ giám sát production của chúng tôi là nguồn đo. Loại trừ theo toàn văn pháp lý: sự cố phòng lab ngoài tầm failover, bảo trì có báo trước, bất khả kháng, lỗi cấu hình phía khách hàng.",
