"d.c2s1": "Hai biến môi trường:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows: <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "Hoặc lưu trong <code>~/.claude/settings.json</code>:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "Chạy <code>claude</code> như thường. Cline: nhà cung cấp <b>Anthropic</b>, cùng base URL + key.",
"d.c3k": "NHÓM · KEY, NHÓM & HẠN MỨC",
"d.c3h": "Mỗi người một key, mỗi key một hạn mức",
"d.c3s1": "Tạo một key cho mỗi đồng đội trong <b>Console → API Keys</b>; đặt <code>hạn mức</code> tháng và allowlist mô hình tùy chọn.",
"d.c3s2": "<b>Nhóm chọn pool định tuyến, không gắn với người</b>: <code>Standard</code> = kênh chính thức tổng hợp (mặc định); <code>Economy</code> = đường riêng rẻ nhất. Một key thuộc một nhóm, đổi lúc nào cũng được.",
"d.c3s3": "Chi tiêu theo key, token theo loại, quota còn lại: <b>Usage &amp; Logs</b> hoặc API sổ cái.",
"d.c4k": "TÍNH PHÍ · GIÁ & CACHE, NÓI THẲNG",
"d.c4h": "Mỗi con số nghĩa là gì",
"d.tblh": "<th>GIÁ</th><th>Ý NGHĨA</th>",
"d.tbl1": "mỗi 1M token prompt gửi đi",
"d.tbl2": "mỗi 1M token sinh ra",
"d.tbl3": "token tiền tố gửi lại, ~10% giá input · cache sống 5–60 phút tùy lab",
"d.c4s1": "<b>Sức khỏe 30 ngày</b> = % yêu cầu thành công trong 30 ngày qua, lưu lượng thật.",
"d.c4s2": "Yêu cầu thất bại (5xx) không bị tính phí; failover chỉ tính mô hình đã trả lời. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA đầy đủ →</a>",
"d.cmh": "Cộng đồng",
"d.cmp": "Builder giúp builder — cấu hình định tuyến, setup agent, chọn mô hình. Đội ngũ đọc hết; gateway-bench và audit log phát triển công khai.",
"st.kick": "TRẠNG THÁI API · CẬP NHẬT MỖI 60 GIÂY", "st2.kick": "TRẠNG THÁI API · TRANG TRẠNG THÁI CÔNG KHAI", "st2.h2": "Uptime luôn minh bạch.", "st2.sub": "Mục tiêu SLA 99,5% · nhật ký uptime 90 ngày và lịch sử sự cố trên <a href=\"/status\">trang trạng thái công khai →</a>", "st2.live": "trực tiếp →", "st2.more": "Xem trạng thái đầy đủ &amp; lịch sử sự cố →",
"st.ok": "Mọi hệ thống hoạt động bình thường",
"st.slaline": "Mục tiêu SLA 99,5% · <a href=\"sla.html\" style=\"color:#fff\">đọc SLA công khai →</a>",
"st.inch": "Lịch sử sự cố",
"st.sub": "Đăng ký nhận tin",
"st.i1": "<b>Đã xử lý — độ trễ tăng trên một kênh GPT.</b> Lưu lượng tự chuyển sang kênh khỏe trong vài giây; yêu cầu thất bại không tính phí.",
"st.i2": "<b>Hoàn tất — bảo trì cơ sở dữ liệu theo kế hoạch.</b> Các endpoint suy luận hoạt động bình thường.",
"st.i3": "<b>Không có sự cố trong 7 ngày qua.</b>",
