"proof.h1": "$1 tín dụng + <span>chạy 3 lần trước khi đăng ký</span>",
"proof.p1": "Together và Segmind đã bỏ gói miễn phí; Novita chỉ còn $0.50. flatkey cho bạn chạy mô hình thật trước cả khi đăng nhập.",
