"proof.t4": "THANH TOÁN NỘI TỆ",
"proof.h4": "Pix, UPI, Alipay — <span>tiền tệ của bạn</span>",
"proof.p4": "Giá theo BRL, INR hoặc CNY khi thanh toán, bảo mật 3DS. Thêm API tương thích Anthropic: trỏ Claude Code hoặc Cline vào một base_url là xong.",
"cmp.h2": "Claude chỉ 67% giá chính thức.<br>Các bên khác tính đủ giá.",
"cmp.sub": "Claude Opus 4.8, $ trên 1M token đầu vào, đo ngày 2026-07-14.",
"cmp.foot": "Together, Novita, Segmind còn không bán Claude chính thức. flatkey: Claude bằng ⅔ giá chính thức — một gói thuê bao, mọi model; enterprise còn rẻ hơn.",
"trust.kick": "TIN CẬY · DÒ TÍNH XÁC THỰC MỖI GIỜ",
"trust.h2": "0 lần tráo mô hình. <em>Mãi mãi.</em><br>Và chúng tôi chứng minh được.",
"trust.p": "Mỗi giờ, mỗi mô hình được đối chiếu với dấu vân tay API chính thức — logits, tokenizer, mẫu từ chối. Nhật ký công khai. Gateway giá rẻ xin niềm tin; flatkey đưa ra bằng chứng.",
"compl.kick": "COMPLIANCE · KIỂM TOÁN CẤP DOANH NGHIỆP",
"compl.h2": "Mỗi token,<br>đều có sổ sách<em>.</em>",
"compl.p": "Sổ cái theo từng yêu cầu: token vào / ra / cache — xuất được, truy cập qua API. Hóa đơn trong 48h, thanh toán 3DS, hạn mức sub-key và danh sách mô hình cho phép.",
"mdl.kick": "MODELS · 100+ MÔ HÌNH CHÍNH THỨC, MỘT KEY",
"mdl.h2": "Mọi phòng lab hàng đầu<em>.</em><br>Một key.",
"mdl.p": "OpenAI, Anthropic, Google, DeepSeek, Alibaba, Zhipu, Moonshot, ByteDance… mô hình mới lên sóng trong 24h — luôn là endpoint thật, không quantize.",
"mdl.cta1": "Bắt đầu — tặng $1",
