"ct.li": "Auf LinkedIn folgen",
"cp.badge": "NEU · flatkey Compute · jetzt live",
"cp.h1": "Ihr gesamtes Compute,<br>ein Key<span class=\"dot\">.</span>",
"cp.sub": "Mieten Sie ganze GPUs stundenweise und loggen Sie sich per SSH ein, deployen Sie jedes Modell als API pro Token und generieren Sie Video sekundenweise — Self-Service, mit einem flatkey Key und einem Guthaben. Jetzt live, ohne Warteliste. Wir horten keine Karten, deshalb bleibt der Preis am Marktboden.",
"cp.cta1": "Compute öffnen — jetzt live →",
"cp.cta2": "Vertrieb kontaktieren",
"cp.a1": "RTX 4090 ab $0.72/hr",
"cp.a2": "SSH & Jupyter",
"cp.a3": "Modelle pro Token",
"cp.a4": "Video sekundenweise",
"cp.a5": "Ein Key · ein Guthaben",
"cp.s1eye": "Die Lücke",
"cp.s1h": "Der Compute-Markt ist überfüllt. Der Kreislauf nicht.",
"cp.s1p": "Fünf Anbieter beherrschen den Roh-GPU-Markt — Vast (günstigster Spot), RunPod (Self-Service), Lambda (Training), Together (Software-Stack), CoreWeave (private Cluster). Keiner schließt den entscheidenden Kreislauf: Modelle, GPUs und Video auf einem Key, einem Guthaben, mit einem Ein-Klick-Weg von der Nutzung pro Token zu einem reservierten, mandantenfähigen, SLA-gestützten dedizierten Endpoint. flatkey hat bereits die Modelle, die Abrechnung und die Nutzer — und Compute ist live: Mieten Sie heute eine GPU, deployen Sie ein Modell oder generieren Sie Video, und stufen Sie gefragte Modelle beim Skalieren auf dediziert hoch.",
"cp.s2eye": "So funktioniert's",
"cp.s2h": "Mieten, deployen oder generieren — Self-Service",
"cp.f1b": "GPU mieten",
"cp.f1s": "Ganze Karte stundenweise, Zugang per SSH und Jupyter",
"cp.f2b": "Modell deployen",
"cp.f2s": "Jedes Modell als API, pro Token",
"cp.f3b": "Video generieren",
"cp.f3s": "Sekundenweise, White-Label",
"cp.f4b": "Ein Guthaben",
"cp.f4s": "Alles wird über Ihr flatkey-Wallet abgerechnet",
"cp.f5b": "Auf dediziert skalieren",
"cp.f5s": "Gefragte Modelle auf reservierte SLA-Endpoints hochstufen",
"cp.s3eye": "Warum flatkey",
"cp.s3h": "Keine weitere GPU-Cloud",
"cp.c1t": "Asset-light — das OpenRouter des Compute",
"cp.c1p": "Wir kaufen keine Karten und tragen keine Capex. Wir aggregieren das Angebot und routen zum Bodenpreis, verpackt in einen einzigen Enterprise-Zugang mit SLA. Günstiger als Besitz, stabiler als roher Spot.",
"cp.c2t": "Inferenz ↔ Compute, geschlossener Kreislauf",
"cp.c2p": "Ihre Modelle, Abrechnung und Ihr Team leben bereits hier. Der Wechsel von \"ein Modell nutzen\" zu \"seine Kapazität reservieren\" ist reibungslos — und eine Rechnung statt zwei Anbieter.",
"cp.c3t": "Apple-Silicon-Flotte mit großem Speicher",
"cp.c3p": "Eine Maschine mit 512GB Unified Memory betreibt ein 671B-Modell auf einem einzigen Node, ergänzt durch eine globale Apple-Silicon-Flotte. Speicherstarke, energieeffiziente Inferenz, die keine reine NVIDIA-Cloud erreicht.",
"cp.c4t": "Enterprise-Niveau, einheitliche Abrechnung",
"cp.c4p": "Private Isolation, Budgets und Team-Kontingente, spend API und ein öffentliches SLA-Ziel — Inferenz und Compute auf einer Rechnung, die Ihr Finanzteam tatsächlich abstimmen kann.",
"cp.s4eye": "Preisanker",
"cp.s4h": "Zum Marktboden bepreist",
"cp.tmodel": "Modell",
"cp.tm1": "Private Cluster",
"cp.tm2": "On-Demand-Cluster",
"cp.tm3": "On-Demand",
"cp.tm4": "Instance / Bare-Metal",
"cp.tm5": "Eigene App deployen",
"cp.tm6a": "ab $1.79/hr",
"cp.tm6b": "ab $0.99/hr",
"cp.tm6c": "Self-Service + dediziert + SLA",
"cp.note": "Self-Service ab heute: Mieten Sie eine RTX 4090 ab $0.72/hr mit SSH, oder betreiben Sie Modelle pro Token und Video sekundenweise — alles aus einem Guthaben. Das Backend-Angebot wird preisbasiert über aggregierte Marktplätze bezogen, sodass ein dedizierter H100-Endpoint weiterhin unter Lambda / CoreWeave / Novita On-Demand landet und dabei Enterprise-SLA, private Isolation und einheitliche Abrechnung hinzufügt, die roher Spot nicht bieten kann. Die Marge stammt aus Routing und Messung, nicht aus dem Vorhalten ungenutzter Hardware. Ankerpreise spiegeln die öffentlichen Tarife vom 2026-07-17 wider; Self-Service-Tarife sind Richtwerte und werden live in der Konsole angezeigt.",
"cp.s5eye": "Für wen",
"cp.s5h": "Gebaut für Teams, die Inferenz im großen Maßstab betreiben",
"cp.w1t": "Agenten- & KI-App-Unternehmen",
"cp.w1p": "Wenige Modelle tragen den Großteil Ihres Traffics. Reservieren Sie dedizierte Kapazität für sie zum Bodenpreis, ohne die Plattform zu verlassen, über die Sie bereits abrechnen.",
"cp.w2t": "Private Deployment & Compliance",
"cp.w2p": "Bringen Sie Ihr eigenes Modell oder Fine-Tune mit, hosten Sie es unter privater Isolation und routen Sie es über Ihre bestehenden Keys und Kontingente.",
"cp.leadh": "Brauchen Sie dedizierte Kapazität oder ein privates Deployment?",
"cp.leadsub": "Self-Service ist in der Konsole live — starten Sie jederzeit. Für einen reservierten Single-Tenant-Endpoint, private Isolation oder ein Mengenangebot sagen Sie uns, was Sie betreiben, und wir melden uns mit Zahlen. English / 中文 beide willkommen.",
"cp.ph1": "Vollständiger Name",
"cp.ph2": "Geschäftliche E-Mail",
"cp.ph3": "Unternehmen",
"cp.ph4": "Modelle & monatliche GPU-hours (geschätzt)",
"cp.ph5": "Was würden Sie auf dediziertem Compute betreiben? (heiße Modelle, Durchsatz, Isolations-/Compliance-Anforderungen…)",
