"mo.h2": "100+ offizielle Modelle. Preise offen.",
"mo.hlb": "<b>Modell-Authentizität, auditiert.</b>",
"mo.hlp": "Jedes Modell wird stündlich gegen seinen offiziellen API-Fingerprint geprüft, Log öffentlich — 'billige Gateways', die still Modelle tauschen, sind genau der Grund, billigen Gateways nicht zu trauen.",
