"mo.audsub": "Realtime-Voice, TTS und Transkription — pro Minute oder 1K Zeichen",
"tu.p1": "Alle 100+ Modelle mit bis zu $45/Monat Nutzung, plus 300 Media Credits für Bild und Video. 10 Requests/min. Jederzeit kündbar.",
"tu.p2": "Bis zu $90/Monat Modellnutzung, 1.200 Media Credits und 30 Requests/min. Für tägliches Coden und Produktion.",
"tu.p3": "Bis zu $300/Monat Nutzung, 5.000 Media Credits, 60 Requests/min und Peak-Priorität. Für intensive Agents und Teams.",
"tu.faqh": "Preis-FAQ",
"tu.q1": "Was enthält ein Plan?",
"tu.a1": "Ein monatliches Nutzungskontingent — bis zu $45 bei Go, $90 bei Pro, $300 bei Max — einsetzbar über alle 100+ Modelle, plus Media Credits für Bild- und Videogenerierung. Kurze 5-Stunden- und 7-Tage-Fenster halten den Dienst für alle schnell.",
"tu.q2": "Ist das ein Monatsabo?",
"tu.a2": "Pay as you go hat kein Abo und kein Ablaufdatum. Go, Pro und Max verlängern sich monatlich und sind jederzeit kündbar; nach dem Monatskontingent nutzt derselbe Key Ihr Pay-as-you-go-Guthaben.",
"tu.q3": "Welche Modelle deckt ein Plan ab?",
"tu.a3": "Jeder Plan deckt GPT, Claude, Gemini, DeepSeek sowie Bild-, Audio- und Videomodelle ab — über ein OpenAI-kompatibles Gateway.",
"tu.q4": "Sehe ich, wie das Guthaben verbraucht wird?",
"tu.a4": "Ja. Nutzung wird pro Modell, Token-Typ und Request-Log gemessen — Teams behalten Kosten im Griff.",
"tu.q5": "Wann Enterprise wählen?",
"tu.a5": "Bei größerem Monatsvolumen, Rechnungsstellung, Einkauf, individuellen Routing-Rabatten oder Team-Kontrollen.",
"uc.kick": "USE CASES · EIN BEFEHL FÜR IHRE CODING AGENTS",
"uc.h1": "Ihr Coding-Agent,<br><span style=\"color:var(--violet)\">33–60 % günstiger als die Liste</span>.",
"uc.sub": "Behalten Sie Ihren CLI-Workflow. Ein Installer richtet Codex, Claude Code oder Image Buddy auf flatkey — ein Guthaben, sichtbare Ausgaben, gleiches SDK.",
"uc.c1h": "Codex, <span>bis zu 33 % günstiger</span>",
"uc.c1p": "OpenAI-kompatiblen Codex-CLI-Workflow behalten, über flatkey geroutet — geringere Kosten, ein Prepaid-Guthaben, sichtbare Ausgaben.",
"uc.c2h": "Claude Code, <span>gleicher Workflow, kleinere Rechnung</span>",
"uc.c2p": "flatkey spricht das Anthropic-Format nativ. Claude Code auf eine base_url zeigen — jede Session läuft über Ihr Guthaben.",
"uc.c3h": "Image Buddy, <span>ein Guthaben auch für Medien</span>",
"uc.c3p": "Der Key Ihrer Textmodelle deckt auch Bildgenerierung ab. Medienausgaben landen im selben Guthaben und Log.",
"ob.h2": "Ihr Key ist aktiv. Los geht's.",
