"rel.h2": "Stabilität, an der Sie<br>uns messen können.",
"rel.p": "Ein Request, fünf Upstream-Kanalklassen. Degradiert ein Kanal, routet der Router automatisch um — und das SLA ist ein öffentliches Dokument, kein Vertriebsversprechen.",
"rel.s1": "unterschriebenes SLA — <a href=\"/sla\" style=\"color:var(--violet-deep);white-space:nowrap\">öffentliche Bedingungen →</a>",
"rel.s2": "Kanalklassen, automatischer Failover",
