"rel.cta2": "SLA & Gutschriften",
"rel.ct": "VERFÜGBARKEIT · EINZELKANAL VS FLATKEY-MESH · LIVE",
"rel.cap": "Fällt ein Upstream aus, erholt sich der Router auf dem nächstbesten offiziellen Kanal — Sie sehen eine einzige flache Linie.",
"why.c1h": "Flagships für ⅔ des Listenpreises",
"why.c1p": "Die Flagships GPT und Claude für ⅔ des Listenpreises. Ein Abo deckt alle 100+ Modelle ab — Text, Bild und Video — mit einem einzigen Key.",
"why.c2h": "Offizielle Endpoints, stündlich verifiziert",
"why.c2p": "Jeder Request trifft die echte Lab-API — kein fp8-Re-Serving, kein stilles Austauschen. 100+ Modelle gegen offizielle Fingerprints geprüft, öffentliches Log.",
"why.c3h": "CLI-nativ. Mit SKILL.md.",
"why.c3p": "Verweise Codex, Claude Code, OpenClaw oder jede Agenten-CLI auf Flatkeys SKILL.md. Der Agent lernt, über einen Key mehr als 300 offizielle Modelle und mehr als 1.000 nutzungsbasierte Tools zu finden und aufzurufen.",
"why.c4h": "Enterprise-Governance",
"why.c4p": "Baumartige Sub-Keys mit Budgets und Allowlists, Ledger-API pro Request, Rechnungen in 48h — auf auditierter Infrastruktur.",
