"lg.fine": "Mit dem Fortfahren akzeptieren Sie die <a href=\"terms.html\">Nutzungsbedingungen</a> und die <a href=\"privacy.html\">Datenschutzerklärung</a>.",
"pr.h2": "Flexible Preise.<br>Alle Modelle inklusive.",
