"ct.h2": "Vertrieb kontaktieren",
"ct.send": "Senden — Antwort binnen 1 Werktag →",
"pr.sub": "Nutzen Sie Pay as you go ohne monatliche Bindung oder wählen Sie Go, Pro oder Max für mehr Modellnutzung. Alle 100+ Modelle sind enthalten — GPT, Claude, Gemini, DeepSeek, Kimi, GLM sowie Seedance Bild &amp; Video. <b>Enterprise-Verträge kosten weniger als Self-Serve</b>.",
"pr.note": "Self-Serve-Preise (PLG). Enterprise ist günstiger — Commit-Volumen, Vertrieb kontaktieren.",
"nav.sla": "SLA",
"s.kick": "SLA · ÖFFENTLICHES ZIEL · ENTERPRISE-GUTSCHRIFTEN",
"s.h1": "Ein SLA, das den<br>Einkauf überzeugt.",
"s.sub": "Kein Vertriebsversprechen: ein öffentliches Dokument mit Verfügbarkeitsziel, Messmethode und definiertem Incident-Prozess. Enterprise-Verträge ergänzen eine vertragliche Gutschriftentabelle und ein höheres Ziel.",
"s.cta1": "Live-Status →",
"s.cta2": "Vollständiger Rechtstext ↗",
"s.cta3": "Enterprise-SLA",
"s.big.k": "MONATLICHE VERFÜGBARKEITSZUSAGE",
"s.big.p": "Gemessen an den abgedeckten Diensten — Router-API, Anthropic-Endpoint, Konsole und Metering — durch unser Produktionsmonitoring, je Kalendermonat. Enterprise: 99,9% mit Prioritäts-Routing.",
"s.p1k": "FAILOVER",
"s.p1h": "5 Kanalklassen, automatisch",
"s.p1p": "Jedes Modell läuft über bis zu fünf Upstream-Kanalklassen. Health-Checks laufen kontinuierlich; degradiert ein Kanal, werden Requests mit automatischen Retries auf den nächstbesten offiziellen Kanal umgeleitet.",
"s.p2k": "FAIRE MESSUNG",
"s.p2h": "Fehler fressen kein Guthaben",
"s.p2p": "Abgerechnet wird nach bestätigten Token-Zahlen nach der Antwort; Fehler von flatkey selbst verbrauchen nie Guthaben. Ein Failover berechnet nur das antwortende Modell.",
"s.p3k": "TRANSPARENZ",
"s.p3h": "Alles selbst nachprüfbar",
"s.p3p": "Die <a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">Statusseite</a> zeigt 90 Tage Uptime pro Komponente; jedes Modell zeigt 30-Tage-Erfolgsraten aus echtem Traffic. Keine synthetischen Zahlen.",
"s.credh": "Service-Gutschriften — Enterprise-Verträge",
"s.credp": "Unter Standardbedingungen erfolgt die Abhilfe fallweise gemäß öffentlichem SLA. Enterprise-Verträge definieren eine vertragliche Gutschriftentabelle — typische Struktur:",
"s.tblh": "<th>MONATSVERFÜGBARKEIT</th><th>GUTSCHRIFT</th><th>AUSZAHLUNG</th>",
"s.row12": "innerhalb von 5 Werktagen nach Freigabe dem Guthaben gutgeschrieben",
"s.row3": "100% der Monatsnutzung gutgeschrieben",
"s.fine": "Gutschriften gelten für die Nutzung des betroffenen Dienstes im betroffenen Monat. Anspruch: E-Mail an support@flatkey.ai binnen 30 Tagen mit Request-IDs oder Zeitstempeln; Messgrundlage sind unsere Monitoring-Aufzeichnungen. Ausschlüsse gemäß Rechtstext: Ausfälle der Modell-Labs außerhalb der Failover-Reichweite, angekündigte Wartung, höhere Gewalt, kundenseitige Konfigurationsfehler.",
"s.clmh": "So läuft ein Anspruch",
"s.st1b": "Erkennen",
"s.st1p": "Degradierung auf der Statusseite oder in eigenen Logs sehen. Request-IDs oder Zeitfenster notieren.",
"s.st2b": "Einreichen",
"s.st2p": "E-Mail an support@flatkey.ai — Betreff „SLA claim“, Konto-E-Mail, betroffener Endpoint, Zeitstempel. Antwort binnen 1 Werktag.",
"s.st3b": "Gutschrift erhalten",
"s.st3p": "Wir gleichen mit dem Produktionsmonitoring ab und schreiben dem Guthaben gut. Kein Streit mit einem Chatbot.",
"s.moreh": "Mehr als 99,5% nötig?",
"s.morep": "Enterprise-Verträge ergänzen ein 99,9%-Ziel, Prioritäts-Routing bei Vorfällen, einen dedizierten Support-Kanal (Slack oder WeChat) und individuelle Gutschriftentabellen — im Vertrag, nicht auf der Folie.",
"s.morec1": "Mit Vertrieb sprechen →",
"s.morec2": "Failover-Doku lesen",
