"d.h1": "Bauen mit flatkey",
"d.hp": "Offizielles Modell-Gateway. Ein Key routet zu 100+ echten Lab-Endpunkten — Text, Video, Audio — mit Vertrags-SLA hinter jedem Call.",
"d.search": "Doku durchsuchen oder einfach fragen…",
"d.st1": "UNTERSCHRIEBENES SLA · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">BEDINGUNGEN</a>",
"d.st2": "TOKENS / MONAT",
"d.st3": "OFFIZIELLE MODELLE",
"d.st4": "PROTOKOLLE: OPENAI + ANTHROPIC",
"d.card1p": "OpenAI-kompatibler Endpoint unter router.flatkey.ai/v1. base_url ändern, SDK behalten — Chat, Tools, Streaming, strukturierte Ausgabe.",
"d.card2p": "Natives Anthropic-API-Format — Claude Code oder Cline auf dieselbe Base URL zeigen, mit dem sk-fk-…-Key. Keine Übersetzungsschicht.",
"d.card3h": "Medienmodelle",
"d.card3p": "Seedance-2.5-Video, Realtime-Sprache, TTS und Transkription — sekunden- oder zeichengenau, vom selben Guthaben.",
"d.card4h": "Team-Governance",
"d.card4p": "Ein Key pro Mitglied mit Limits und Allowlists; Ledger pro Request, Quoten und Spend-API für die Finanzabteilung.",
"d.qsh": "Mit einem Call starten",
"d.qsp": "Die meisten starten hier: Key in der Konsole anlegen, base_url ändern, Request senden. Drei Zeilen, keine Infrastruktur.",
"d.llm": "Sie bauen mit einem KI-Agenten? Vollständigen Index unter <a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a> abrufen — jede Seite hat einen Markdown-Spiegel (.md).",
"d.gh": "Guides — die vier Fragen, die alle stellen",
"d.c1k": "CODING AGENTS · CODEX CLI",
"d.c1h": "Codex verbinden",
"d.c1s1": "Einzeiler: <span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> und im Installer <code>Codex CLI</code> wählen.",
"d.c1s2": "Manuell: in Codex <b>API key login</b> wählen, Base URL <code>https://router.flatkey.ai/v1</code>, <code>sk-fk-…</code>-Key einfügen.",
"d.c1s3": "Gruppe liefert 503? Key im Key-Editor in eine andere Gruppe verschieben (siehe Gruppen & Routing).",
"d.c2k": "CODING AGENTS · ANTHROPIC-PROTOKOLL",
"d.c2h": "Claude Code / Cline verbinden",
"d.c2s1": "Zwei Umgebungsvariablen:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows: <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "Oder in <code>~/.claude/settings.json</code> persistieren:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "<code>claude</code> wie gewohnt starten. Cline: Provider <b>Anthropic</b>, gleiche Base URL + Key.",
"d.c3k": "TEAMS · KEYS, GRUPPEN & QUOTEN",
"d.c3h": "Ein Key pro Person, ein Limit pro Key",
"d.c3s1": "Pro Teammitglied einen Key in <b>Console → API Keys</b> anlegen; monatliches <code>Limit</code> und optionale Modell-Allowlist je Key setzen.",
"d.c3s2": "<b>Gruppen wählen den Routing-Pool, nicht die Person</b>: <code>Standard</code> = aggregierte offizielle Kanäle (Default); <code>Economy</code> = günstigste dedizierte Leitung. Ein Key gehört zu einer Gruppe, jederzeit umziehbar.",
"d.c3s3": "Ausgaben pro Key, Tokens nach Typ, Restquote: <b>Usage &amp; Logs</b> oder Ledger-API.",
"d.c4k": "ABRECHNUNG · PREISE & CACHE, KLARTEXT",
"d.c4h": "Was jede Zahl bedeutet",
"d.tblh": "<th>PREIS</th><th>BEDEUTUNG</th>",
"d.tbl1": "pro 1M gesendeter Prompt-Tokens",
"d.tbl2": "pro 1M generierter Tokens",
"d.tbl3": "erneut gesendete Präfix-Tokens, ~10% des Input-Preises · Cache lebt 5–60 Min je Lab",
"d.c4s1": "<b>30-Tage-Health</b> = % erfolgreicher Requests der letzten 30 Tage, echter Traffic.",
"d.c4s2": "Fehlgeschlagene Requests (5xx) werden nie berechnet; Failover berechnet nur das antwortende Modell. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">Volles SLA →</a>",
"d.cmh": "Community",
"d.cmp": "Builder helfen Buildern — Routing-Configs, Agent-Setups, Modellwahl. Das Team liest alles mit; gateway-bench und das Audit-Log entstehen offen.",
"st.kick": "API-STATUS · ALLE 60 SEKUNDEN AKTUALISIERT", "st2.kick": "API-STATUS · ÖFFENTLICHE STATUSSEITE", "st2.h2": "Uptime, öffentlich dokumentiert.", "st2.sub": "SLA-Ziel 99,5% · 90-Tage-Uptime-Log und Vorfallhistorie auf der <a href=\"/status\">öffentlichen Statusseite →</a>", "st2.live": "live →", "st2.more": "Vollständigen Status &amp; Vorfallhistorie ansehen →",
"st.ok": "Alle Systeme betriebsbereit",
"st.slaline": "SLA-Ziel 99,5% · <a href=\"sla.html\" style=\"color:#fff\">öffentliches SLA lesen →</a>",
"st.inch": "Vorfallhistorie",
"st.sub": "Updates abonnieren",
"st.i1": "<b>Gelöst — erhöhte Latenz auf einem GPT-Kanal.</b> Traffic in Sekunden automatisch umgeleitet; fehlgeschlagene Requests nicht berechnet.",
"st.i2": "<b>Abgeschlossen — geplante Datenbankwartung.</b> Inference-Endpoints liefen normal weiter.",
"st.i3": "<b>Keine Vorfälle in den letzten 7 Tagen.</b>",
"st.ago": "vor 90 Tagen",
