"proof.t1": "GRATIS STARTEN",
"proof.h1": "$1 Guthaben + <span>3 Läufe vor der Registrierung</span>",
"proof.p1": "Together und Segmind haben ihre Gratis-Stufen gestrichen; Novita ist bei $0.50. Bei flatkey läufst du echte Modelle schon vor dem Login.",
"proof.t2": "SMARTES ROUTING",
"proof.h2": "flatkey-auto, <span>ohne Routing-Gebühr</span>",
"proof.p2": "Ein Modellname; das Gateway wählt pro Request das beste offizielle Modell — task- und health-bewusst, immer zum niedrigsten Multiplikator.",
"proof.t3": "VERTRAUEN · NULL QUANTISIERUNG",
"proof.h3": "Offizielle APIs, <span>stündlich auditiert</span>",
"proof.p3": "Kein fp8-Re-Serving, kein stilles Austauschen. Jedes Modell wird stündlich gegen seinen offiziellen Fingerprint geprüft — öffentliches Log, 100+ Modelle.",
"proof.t4": "LOKAL BEZAHLEN",
"proof.h4": "Pix, UPI, Alipay — <span>deine Währung</span>",
"proof.p4": "Preise in BRL, INR oder CNY im Checkout, 3DS-gesichert. Plus Anthropic-kompatible API: Claude Code oder Cline auf eine base_url zeigen — fertig.",
"cmp.h2": "Claude für 67 % des Listenpreises.<br>Alle anderen berechnen den vollen Preis.",
"cmp.sub": "Claude Opus 4.8, $ pro 1M Input-Tokens, gemessen am 2026-07-14.",
"cmp.foot": "Together, Novita und Segmind verkaufen offizielles Claude gar nicht. flatkey: Claude für ⅔ des Listenpreises — ein Abo, alle Modelle; Enterprise noch günstiger.",
"trust.kick": "VERTRAUEN · STÜNDLICHE AUTHENTIZITÄTS-PROBES",
"trust.h2": "0 ausgetauschte Modelle. <em>Niemals.</em><br>Und wir beweisen es.",
"trust.p": "Jede Stunde wird jedes Modell gegen seinen offiziellen API-Fingerprint geprüft — Logits, Tokenizer, Refusal-Muster. Das Log ist öffentlich. Billige Gateways bitten um Vertrauen; flatkey zeigt Belege.",
"compl.kick": "COMPLIANCE · ENTERPRISE-AUDITIERBARKEIT",
"compl.h2": "Jeder Token,<br>im Register<em>.</em>",
"compl.p": "Ledger pro Request mit Input-, Output- und Cache-Tokens — exportierbar, per API zugänglich. Rechnungen in 48h, 3DS-Zahlungen, Sub-Key-Limits und Modell-Allowlists.",
"mdl.kick": "MODELLE · 100+ OFFIZIELLE, EIN KEY",
"mdl.h2": "Jedes Frontier-Lab<em>.</em><br>Ein Key.",
"mdl.p": "OpenAI, Anthropic, Google, DeepSeek, Alibaba, Zhipu, Moonshot, ByteDance… neue Modelle binnen 24h nach Release — immer echte Endpoints.",
"mdl.cta1": "Loslegen — $1 geschenkt",
"mdl.cta2": "Alle 100+ Modelle ansehen",
