"cp.note": "Self-serve mulai hari ini: sewa RTX 4090 mulai $0.72/hr dengan SSH, atau jalankan model per token dan video per detik — semua dari satu saldo. Pasokan backend disumber berdasarkan harga di marketplace agregat, sehingga endpoint H100 khusus tetap berada di bawah Lambda / CoreWeave / Novita on-demand, sambil menambahkan SLA enterprise, isolasi privat, dan penagihan terpadu yang tak bisa diberikan spot mentah. Margin datang dari perutean dan pengukuran, bukan dari menanggung perangkat keras menganggur. Harga jangkar mencerminkan tarif publik pada 2026-07-17; tarif self-serve bersifat indikatif dan ditampilkan langsung di konsol.",
