"nav.sla": "SLA",
"s.kick": "SLA · TARGET PUBLIK · KREDIT ENTERPRISE",
"s.h1": "SLA yang siap<br>dibawa ke bagian pengadaan.",
"s.sub": "Bukan janji sales: dokumen publik dengan target ketersediaan, metode pengukuran, dan proses insiden yang jelas. Kontrak enterprise menambah tabel kredit kontraktual dan target lebih tinggi.",
"s.cta1": "Status langsung →",
"s.cta2": "Teks hukum lengkap ↗",
"s.cta3": "SLA Enterprise",
"s.big.k": "KOMITMEN KETERSEDIAAN BULANAN",
"s.big.p": "Diukur pada layanan tercakup — API router, endpoint Anthropic, konsol dan metering — oleh monitor produksi kami, per bulan kalender. Paket enterprise: 99,9% dengan routing prioritas.",
"s.p1k": "FAILOVER",
"s.p1h": "5 kelas kanal, otomatis",
"s.p1p": "Setiap model dilayani lewat hingga lima kelas kanal upstream. Health check berjalan terus; saat satu kanal menurun, permintaan dialihkan ke kanal resmi terbaik berikutnya dengan retry otomatis.",
"s.p2k": "PENGUKURAN ADIL",
"s.p2h": "Error tidak memakan saldo",
"s.p2p": "Penagihan diselesaikan berdasar jumlah token terkonfirmasi setelah respons; error dari flatkey sendiri tidak pernah memakai saldo. Failover hanya menagih model yang menjawab.",
"s.p3k": "TRANSPARANSI",
"s.p3h": "Semua bisa Anda verifikasi",
"s.p3p": "Halaman <a href=\"status.html\" style=\"color:var(--violet-deep);font-weight:650\">status</a> menampilkan uptime 90 hari per komponen; tiap model menampilkan tingkat sukses 30 hari dari trafik nyata. Tanpa angka sintetis.",
"s.credh": "Kredit layanan — perjanjian enterprise",
"s.credp": "Dalam ketentuan standar, pemulihan ditangani kasus per kasus sesuai SLA publik. Perjanjian enterprise mendefinisikan tabel kredit kontraktual — struktur tipikal:",
"s.tblh": "<th>KETERSEDIAAN BULANAN</th><th>KREDIT</th><th>CARA CAIR</th>",
"s.row12": "masuk ke saldo dalam 5 hari kerja setelah klaim disetujui",
"s.row3": "100% pemakaian bulan itu dikreditkan",
"s.fine": "Kredit berlaku untuk pemakaian layanan terdampak di bulan terdampak. Klaim: email support@flatkey.ai dalam 30 hari dengan request ID atau stempel waktu; catatan monitoring produksi kami menjadi sumber pengukuran. Pengecualian mengikuti teks hukum lengkap: gangguan lab model di luar jangkauan failover, pemeliharaan terjadwal dengan pemberitahuan, force majeure, dan kesalahan konfigurasi pelanggan.",
"s.clmh": "Cara kerja klaim",
"s.st1b": "Deteksi",
"s.st1p": "Lihat degradasi di halaman status atau log Anda sendiri. Catat request ID atau rentang waktunya.",
"s.st2b": "Ajukan",
"s.st2p": "Email support@flatkey.ai — subjek \"SLA claim\", email akun, endpoint terdampak, stempel waktu. Dibalas dalam 1 hari kerja.",
"s.st3b": "Terima kredit",
"s.st3p": "Kami rekonsiliasi dengan monitoring produksi dan mengkreditkan saldo Anda. Tanpa berdebat dengan chatbot.",
"s.moreh": "Butuh lebih dari 99,5%?",
"s.morep": "Perjanjian enterprise menambah target 99,9%, routing prioritas saat insiden, kanal dukungan khusus (Slack atau WeChat), dan skema kredit khusus — di kontrak, bukan di slide.",
"s.morec1": "Bicara dengan sales →",
