"d.h1": "Bangun dengan flatkey",
"d.hp": "Gateway model resmi. Satu key merutekan ke 100+ endpoint lab asli — teks, video, suara — dengan SLA tertandatangan di tiap panggilan.",
"d.search": "Cari di dokumen, atau tanyakan apa saja…",
"d.st1": "SLA DITANDATANGANI · <a href=\"sla.html\" style=\"color:var(--violet-deep)\">KETENTUAN</a>",
"d.st2": "TOKEN / BULAN",
"d.st3": "MODEL RESMI",
"d.st4": "PROTOKOL: OPENAI + ANTHROPIC",
"d.card1p": "Endpoint kompatibel OpenAI di router.flatkey.ai/v1. Ganti base_url, SDK tetap — chat, tools, streaming, structured output.",
"d.card2p": "Format API Anthropic asli — arahkan Claude Code atau Cline ke base URL yang sama dengan key sk-fk-…. Tanpa lapisan terjemahan.",
"d.card3h": "Model media",
"d.card3p": "Video Seedance 2.5, suara realtime, TTS dan transkripsi — per detik atau karakter, dari saldo yang sama.",
"d.card4h": "Tata kelola tim",
"d.card4p": "Satu key per anggota dengan batas dan allowlist; buku besar per permintaan, kuota, dan API pengeluaran untuk finance.",
"d.qsh": "Mulai dengan satu panggilan",
"d.qsp": "Kebanyakan mulai di sini: buat key di konsol, ganti base_url, kirim permintaan. Tiga baris, tanpa infrastruktur.",
"d.llm": "Membangun dengan agent AI? Ambil indeks lengkap di <a href=\"https://docs.flatkey.ai/llms.txt\">/llms.txt</a> — tiap halaman punya cermin markdown (.md).",
"d.gh": "Panduan — empat hal yang paling sering ditanya",
"d.c1k": "CODING AGENTS · CODEX CLI",
"d.c1h": "Hubungkan Codex",
"d.c1s1": "Satu baris: <span class=\"blk\">curl -fsSL https://flatkey.ai/install.sh | bash</span> lalu pilih <code>Codex CLI</code> saat ditanya.",
"d.c1s2": "Manual: di Codex pilih <b>API key login</b>, base URL <code>https://router.flatkey.ai/v1</code>, tempel key <code>sk-fk-…</code> Anda.",
"d.c1s3": "Grup mengembalikan 503? Pindahkan key ke grup lain di editor key (lihat Grup & routing).",
"d.c2k": "CODING AGENTS · PROTOKOL ANTHROPIC",
"d.c2h": "Hubungkan Claude Code / Cline",
"d.c2s1": "Dua variabel lingkungan:<span class=\"blk\">export ANTHROPIC_BASE_URL=https://router.flatkey.ai\nexport ANTHROPIC_API_KEY=sk-fk-…</span>Windows: <code>setx ANTHROPIC_BASE_URL …</code>",
"d.c2s2": "Atau simpan di <code>~/.claude/settings.json</code>:<span class=\"blk\">{\"env\": {\n  \"ANTHROPIC_BASE_URL\": \"https://router.flatkey.ai\",\n  \"ANTHROPIC_API_KEY\": \"sk-fk-…\"\n}}</span>",
"d.c2s3": "Jalankan <code>claude</code> seperti biasa. Cline: penyedia <b>Anthropic</b>, base URL + key yang sama.",
"d.c3k": "TIM · KEY, GRUP & KUOTA",
"d.c3h": "Satu orang satu key, satu key satu batas",
"d.c3s1": "Buat satu key per rekan di <b>Console → API Keys</b>; atur <code>batas</code> bulanan dan allowlist model opsional per key.",
"d.c3s2": "<b>Grup memilih pool routing, bukan orangnya</b>: <code>Standard</code> = kanal resmi teragregasi (default); <code>Economy</code> = jalur khusus termurah. Satu key milik satu grup, bisa dipindah kapan saja.",
"d.c3s3": "Pengeluaran per key, token per jenis, sisa kuota: <b>Usage &amp; Logs</b> atau API buku besar.",
"d.c4k": "PENAGIHAN · HARGA & CACHE, TERUS TERANG",
"d.c4h": "Arti setiap angka",
"d.tblh": "<th>HARGA</th><th>ARTI</th>",
"d.tbl1": "per 1M token prompt terkirim",
"d.tbl2": "per 1M token dihasilkan",
"d.tbl3": "token prefiks terkirim ulang, ~10% harga input · cache hidup 5–60 mnt per lab",
"d.c4s1": "<b>Kesehatan 30 hari</b> = % permintaan sukses dalam 30 hari terakhir, trafik nyata.",
"d.c4s2": "Permintaan gagal (5xx) tidak pernah ditagih; failover hanya menagih model yang menjawab. <a href=\"sla.html\" style=\"color:var(--violet-deep);font-weight:650\">SLA lengkap →</a>",
"d.cmh": "Komunitas",
"d.cmp": "Builder menjawab builder — config routing, setup agent, pilihan model. Tim membaca semuanya; gateway-bench dan audit log dikembangkan terbuka.",
"st.kick": "STATUS API · DIPERBARUI TIAP 60 DETIK", "st2.kick": "STATUS API · HALAMAN STATUS PUBLIK", "st2.h2": "Uptime, terbuka untuk umum.", "st2.sub": "Target SLA 99,5% · log uptime 90 hari dan riwayat insiden di <a href=\"/status\">halaman status publik →</a>", "st2.live": "langsung →", "st2.more": "Lihat status lengkap &amp; riwayat insiden →",
"st.ok": "Semua sistem beroperasi",
"st.slaline": "Target SLA 99,5% · <a href=\"sla.html\" style=\"color:#fff\">baca SLA publik →</a>",
"st.inch": "Riwayat insiden",
"st.sub": "Berlangganan",
"st.i1": "<b>Terselesaikan — latensi naik di satu kanal GPT.</b> Trafik dialihkan otomatis dalam hitungan detik; permintaan gagal tidak ditagih.",
"st.i2": "<b>Selesai — pemeliharaan database terjadwal.</b> Endpoint inferensi tetap normal.",
